(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-rollout-bandit-scheduling"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-1\">一 · 一次预填队列被“简单题”淹没的事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-2\">二 · 它精确解决的那一类问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-3\">三 · 它明确不解决的问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-4\">四 · 适用边界的判定清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-5\">五 · 与相邻机制的接缝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-6\">六 · 当固定调度把算力喂给“已经学会的题”：边界、失效与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-7\">七 · 统计量的写入路径：从采样回传到后验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-8\">八 · 优先级打分：UCB 式信息增益上界的构造</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-9\">九 · 配额分配：条数与 max_len 的联合放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-10\">十 · 采样执行与回传：引擎侧的只读契约</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-11\">十一 · 后验更新与周期性重算：算力迁移的时序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-12\">十二 · 失败模式在步骤链上的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-13\">十三 · 从“信息增益”到可计算的上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-14\">十四 · 推导的关键一步：为什么方差要乘在外面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-15\">十五 · 伪代码：从统计到配额队列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-16\">十六 · 非均匀采样对训练侧的连带代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-17\">十七 · 滞后与边界：队列刷新节奏决定有效性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-18\">十八 · 边界、失效条件与系统代价：UCB 分配在真实 rollout 回路里的摩擦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-19\">十九 · 负载配方：什么样的请求形态才吃得住这套调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-20\">二十 · 长度分布与批大小的耦合：max_len 放大是双刃剑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-21\">二十一 · 负载不对时的三种塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-22\">二十二 · 配方判定：四条可检查的负载特征</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-23\">二十三 · 配额兑现的接口：优先级队列要带什么字段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-24\">二十四 · 负载配方：bandit 调度吃什么样的请求分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-25\">二十五 · 硬件档位：按优先级分层而不是按峰值选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-26\">二十六 · 并行拓扑：让优先级决定 TP/EP 而不是让模型决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-27\">二十七 · 量化方案：优先级分层对应精度分层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-28\">二十八 · KV 策略：按优先级分配池容量与驻留时长</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-29\">二十九 · 调度参数：c、重算周期与组内归一化的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-30\">三十 · 配方落地时的三条硬边界：统计冷启动、组内基线失真与队列滞后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-31\">三十一 · 显存：非均匀配额如何把峰值推到采样侧</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-32\">三十二 · 带宽：权重读取被摊薄，KV 读写被集中</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-33\">三十三 · 通信：并行采样把集合通信从稀疏推向密集</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-34\">三十四 · 功耗与热：算力集中带来的局部热点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-35\">三十五 · 尾延迟：优先级队列滞后与组内不一致的叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-36\">三十六 · 规模上去以后哪里先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-37\">三十七 · 规模上去以后，先崩的是队列重算与组内归一化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-38\">三十八 · 精度漂移：UCB 分数被噪声主导的早期失败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-39\">三十九 · OOM 与批抖动：max_len 放大带来的显存非线性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-40\">四十 · 路由不均：优先级队列与引擎读取的滞后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-41\">四十一 · 尾延迟尖刺：非均匀采样的组内失衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-42\">四十二 · 监控面与回滚：把失败模式映射到可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-43\">四十三 · 同族算法的谱系与选择维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-44\">四十四 · 与在线剪枝的边界：分配前 vs 分配后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-45\">四十五 · 与课程式调度的取舍：全局阈值 vs 逐 prompt 后验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-46\">四十六 · 与分页 KV、前缀共享的耦合条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-47\">四十七 · 决策表：给定条件下的算法选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-bandit-scheduling-sec-48\">四十八 · 选型后的接口与滞后预算</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:577px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 577.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout调度器为每个prompt维护历史统计：通过率、reward方…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按上下文bandit规则计算每个prompt的采样优先级分数（信息增益上界…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">高优先级prompt获得更多采样条数与更长max_len，低优先级prom…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样结果回传后更新该prompt的统计量，bandit后验随之更新</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器周期性重算优先级，把算力从已收敛题目迁移到新出现的高不确定性题目</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-rollout-bandit-scheduling-sec-1\">一 · 一次预填队列被“简单题”淹没的事故</h3>\n<p>某在线 RL 训练任务在 2026 年初的一次扩容后出现了典型的退化：策略改进曲线在扩容后的头几个小时内几乎走平，而 GPU 利用率却维持在满载。排查发现 rollout 引擎的调度仍按 prompt 长度分桶——长 prompt 优先获得更大的批与更长的 max_len。扩容前这个启发式尚能工作，因为长 prompt 大多来自题库中较难的合成题；扩容后新引入的一批长上下文样本恰好是模型已经高通过率的模板题，它们占据了绝大部分预填算力与 KV 显存，真正高不确定性的短 prompt 被挤到队尾，采样条数被压到组内最小。结果是单位 FLOPs 的策略改进骤降，GRPO 组内基线因为简单题几乎全对而塌缩，梯度信号变稀。</p>\n<p>这个事故的根因不是引擎吞吐不够，而是<strong>采样预算的分配依据与样本的信息价值脱钩</strong>。RL rollout 的样本价值随训练进程漂移：一道题在早期是高不确定性的探索目标，在策略收敛后变成零信息量的重复确认。任何静态的、与训练状态无关的排序键——prompt 长度、前缀局部性、词表分布——都无法跟踪这种漂移。rollout 上下文 bandit 调度要解决的正是这件事：把每个 prompt 的采样预算当成一个带上下文信息的 bandit 问题，用历史 reward 统计估计其信息增益，动态决定这一轮给它多少条采样、多长的生成长度。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-2\">二 · 它精确解决的那一类问题</h3>\n<p>算法的作用域可以形式化为：给定一个 prompt 池 $\\mathcal{P}$、总采样轮次 $N$ 与每个 prompt 的已采样条数 $n_i$，在单位算力预算下最大化策略改进量。调度器为每个 prompt 维护四元组统计——通过率 $\\hat{p}_i$、reward 方差 $\\widehat{\\mathrm{Var}}[R|x_i]$、平均生成长度 $\\bar{L}_i$、最近更新轮次 $t_i$——并据此构造 UCB 式信息增益上界：</p>\n<div class=\"formula\">$$s_i=\\hat{\\mu}_i+c\\sqrt{\\frac{\\ln N}{n_i}},\\qquad \\hat{\\mu}_i \\propto \\hat{p}_i\\bigl(1-\\hat{p}_i\\bigr)\\cdot\\widehat{\\mathrm{Var}}[R|x_i]$$</div>\n<p>其中 $\\hat{\\mu}_i$ 不是 reward 均值本身，而是由通过率与方差联合估计的<em>信息增益均值</em>：通过率接近 0 或 1 的题目梯度贡献趋零，方差大的题目意味着组内 reward 分散、advantage 有区分度。第二项是探索项，$n_i$ 小则分数被抬高，保证新题与久未更新的题不被饿死。排序后按分数分配本轮配额，高优先级 prompt 同时获得更多采样条数与更长的 max_len——因为高不确定性题目往往需要更长思维链才能暴露分歧。采样结果回传后更新统计量，调度器周期性重算优先级，把算力从已收敛题目迁移到新出现的高不确定性题目。</p>\n<p>代价侧必须说清楚：这套机制把算力从“均匀覆盖”改成“按信息增益倾斜”，收益体现在单位 FLOPs 的策略改进，而不是单请求时延。它天然不适合以单请求 P99 为 SLO 的在线服务形态——那类场景需要的是批不变性与稳定时延，属于另一条路线的工作。它也不解决采样内核本身的效率问题：调度器只读优先级队列，rollout 引擎的采样内核一行不改，因此分页 KV、连续批处理这些底层机制的优化收益与它是正交叠加关系。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-3\">三 · 它明确不解决的问题</h3>\n<p>边界的第一条是<strong>统计稀疏</strong>。训练早期每个 prompt 的历史样本极少，通过率与 reward 方差估计噪声大，UCB 分数容易被偶然的高方差样本主导，算力被错配到伪高不确定性题目——一个只采样过两次、恰好两次 reward 相反的 prompt 会拿到虚高的 $s_i$。这不是调 $c$ 能根治的，因为噪声来自后验本身不成立，而非探索强度失配。工程上的缓解是冷启动阶段退回按池分层轮转、等每个 prompt 攒够最小样本数再启用 bandit 打分，代价是前期若干轮算力分配偏保守。</p>\n<p>第二条是<strong>组内样本数不一致带来的训练侧复杂度</strong>。非均匀采样意味着同一个 GRPO 组里不同 prompt 的采样条数不同，若训练侧仍按固定组大小做 advantage 归一化，组内基线失真、梯度方差被放大。这不是调度器能单方面修好的，必须在训练侧按组实际样本数修正归一化分母，或对低配额组做加权。调度与训练解耦的部署配方在这里有代价：解耦让 rollout 引擎无需改内核，但把一致性负担推给了训练侧实现。</p>\n<p>第三条是<strong>队列滞后</strong>。优先级队列周期性重算与 rollout 引擎读取之间存在时间差，题目已收敛但队列未刷新时，算力仍按旧分数分配。重算频率必须匹配训练节奏：太快则重算开销吃掉收益，太慢则迁移不及时。规模上限也受此约束——prompt 池越大，单次全量重算的排序开销越高，通常需要用增量更新或分片重算把开销压到可接受范围。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-4\">四 · 适用边界的判定清单</h3>\n<p>判断一个 rollout 场景是否该上这套调度，可以按下面几条硬性条件过一遍，任何一条不满足都应先解决前置问题而不是调 bandit 参数。</p>\n<table class=\"mini\"><thead><tr><th>判定项</th><th>满足条件</th><th>不满足时的后果</th></tr></thead><tbody>\n<tr><td>prompt 池稳定性</td><td>池内题目在若干轮内可重复采样，统计量有意义</td><td>每题只出现一次，后验永远稀疏，退化为随机分配</td></tr>\n<tr><td>统计更新频率</td><td>重算周期与策略更新节奏同量级</td><td>队列滞后，收敛题继续吃算力</td></tr>\n<tr><td>训练侧归一化</td><td>advantage 按组实际样本数修正</td><td>梯度方差放大，组内基线失真</td></tr>\n<tr><td>SLO 口径</td><td>以单位 FLOPs 的策略改进衡量</td><td>以单请求时延为 SLO 时，倾斜分配直接违反时延约束</td></tr>\n<tr><td>池规模</td><td>重算开销可被增量/分片摊薄</td><td>全量排序成为调度器自身瓶颈</td></tr>\n</tbody></table>\n<p>一个具体的适用例子：数学推理 RL，题库固定、每题可反复采样、策略在若干轮内显著漂移。早期所有题通过率都低，bandit 近似均匀；中期简单题通过率趋近 1，$s_i$ 中的 $\\hat{p}_i(1-\\hat{p}_i)$ 项把它压下去，配额自动流向中等难度题；后期新引入的难题以高探索项进入队列并获得更长 max_len。整个过程中 rollout 引擎只读队列，采样内核不变。</p>\n<p>一个具体的反例：开放式对话的在线 RL，prompt 来自实时流量、几乎不重复。此时每个 prompt 的 $n_i$ 恒为 1，UCB 探索项对所有 prompt 相同，分数退化为单样本 reward 的函数，调度等价于按瞬时 reward 排序——既无统计意义，又会把算力压到偶然低 reward 的样本上。这类场景应先做 prompt 聚类或语义去重，把“同一 prompt”的定义放宽到“同一语义簇”，再谈 bandit。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-5\">五 · 与相邻机制的接缝</h3>\n<p>这套调度处在 rollout 流水线的上游决策层，它输出的是“给谁多少条、多长”的配额，而不是“怎么采得快”。配额下发后，执行侧的分页 KV 批量、分块预填、预填解码分离等机制决定这些配额能否被高效兑现；前缀 KV 共享决定同一 prompt 的多条并行采样能否摊薄预填成本。调度器与这些机制的关系是单向的：它只写优先级队列，不感知执行侧如何组批。这也意味着当执行侧因显存压力被迫缩小批时，高优先级 prompt 的长 max_len 会与低优先级 prompt 的短生成争抢同一批资源，配额的实际兑现率需要用队列深度与批容量的比值来监控——这个比值持续偏低时，应先修执行侧的批调度，而不是继续加大 bandit 的倾斜力度。</p>\n<p>另一个接缝在训练侧：bandit 后验的更新依赖 rollout 回传的 reward，而 reward 的分布本身随策略漂移。若 reward 模型或验证器在同一时期被替换，历史统计量会跨越两个不可比的分布，$s_i$ 的均值项失真。工程判断是：reward 口径变更时必须重置对应 prompt 的统计量或引入折扣因子，把旧样本的权重压下去，否则调度器会把算力持续投向一个已经不再高不确定性的题目——这正是开篇事故在另一个维度上的重演。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-6\">六 · 当固定调度把算力喂给“已经学会的题”：边界、失效与代价</h3>\n\n<p>线上事故的形状通常不是崩溃，而是“曲线还在动、但斜率没了”。某轮 RL 训练中，rollout 调度仍按 prompt 长度分桶：长 prompt 优先、短 prompt 排队。训练推进到中段，长 prompt 池里大量题目通过率已接近饱和，采样仍在按长度配额持续灌入；与此同时新混入的一批短 prompt 通过率在 0.2–0.5 之间剧烈波动，却因长度分桶被压到队尾。结果是单位 FLOPs 的策略改进肉眼可见地变平：GPU 利用率不低、rollout 吞吐不低，但 GRPO 组内 advantage 几乎全为零——因为被采样的题已经“没有信息量”。这个事故的根因不是采样内核慢，而是调度器把一个**随训练进程漂移的量**（样本价值）当成了**静态属性**（prompt 长度、前缀局部性）。上下文 bandit 调度正是针对这一漂移：它把每个 prompt 的采样预算当作一次带上下文的决策，用历史通过率与 reward 方差估计信息增益，按 UCB 式规则动态分配采样条数与 max_len。需要说清的是它**不解决**什么：它不改变采样内核的数值路径，不解决 KV cache 碎片与显存容量问题，也不替代分离式预填/解码的拓扑设计；它只回答“这一轮该给谁多少条、多长”这一个问题。</p>\n\n<p>失效条件集中在统计稀疏与队列滞后两处。训练早期每个 prompt 的历史样本极少，通过率与 reward 方差的估计噪声大，UCB 分数容易被偶然出现的高方差样本主导，算力被错配到“伪高不确定性”题目上——这些题看起来方差大，实则只是样本太少。此时分数公式里的探索项会放大噪声：</p>\n\n<div class=\"formula\">$$s_i=\\hat{\\mu}_i+c\\sqrt{\\frac{\\ln N}{n_i}}$$</div>\n\n<p>其中 $\\hat{\\mu}_i$ 由通过率与 reward 方差估计的信息增益均值给出，$n_i$ 是该 prompt 已采样条数，$N$ 为总采样轮次，$c$ 控制探索强度。$n_i$ 很小时根号项主导，$s_i$ 几乎只反映“采得少”而非“值得采”，调度器会把配额反复推给冷启动题目，形成一轮伪探索。工程上的对策不是调小 $c$，而是给 $n_i$ 设下限、在统计未达阈值前退回按池均匀分配，让 bandit 只在后验足够厚的 prompt 上生效。第二处失效是滞后：优先级队列周期性重算，rollout 引擎读取队列之间存在时间差，题目已收敛但队列未刷新时，算力仍按旧分数分配，迁移不及时。这要求重算周期与训练步节奏匹配，且队列需带版本号，引擎读到过期版本时按保守配额回退。</p>\n\n<p>系统代价有三块，且都落在训练侧而非推理侧。其一是统计开销：调度器要为每个 prompt 维护通过率、reward 方差、平均生成长度与最近更新轮次，优先级队列的重算开销构成 prompt 池规模的上限——池子越大，单轮排序与配额分配的 CPU 侧成本越不可忽略，这也是适用边界“池规模与统计更新频率需匹配训练节奏”的由来。其二是负载形态变化：请求形态变为同一 prompt 的多条并行采样，批大小随优先级动态变化，高优先级 prompt 的采样条数与 max_len 同时放大，单批内序列长度方差上升，KV cache 峰值与显存碎片压力随之变大；SLO 也不再以单请求时延衡量，而以单位 FLOPs 的策略改进衡量，这意味着容量规划的口径要从 tokens/s 切换到“有效梯度样本/s”。其三是训练侧实现复杂度：非均匀采样使同一 GRPO 组内样本条数不一致，若仍按固定组大小做 advantage 归一化，组内基线失真、梯度方差被放大，必须按组实际样本数修正归一化。下表对比两种调度在四个维度上的差异：</p>\n\n<table class=\"mini\"><thead><tr><th>维度</th><th>固定长度/局部性调度</th><th>上下文 bandit 调度</th></tr></thead><tbody><tr><td>算力去向</td><td>按 prompt 长度静态分配</td><td>按信息增益上界动态分配</td></tr><tr><td>组内样本数</td><td>均匀，归一化简单</td><td>非均匀，需按组修正</td></tr><tr><td>显存/带宽</td><td>批内长度较齐整</td><td>批内长度方差大，KV 峰值抬升</td></tr><tr><td>失效点</td><td>中后期喂给已收敛题</td><td>早期统计稀疏、队列滞后</td></tr></tbody></table>\n\n<p>一个具体的工程判断：当 prompt 池中通过率分布高度偏斜（大量题目已饱和、少数题目剧烈波动）时，bandit 调度的收益最明显；反之若池子小、题目难度均匀、训练步数短，统计噪声与队列滞后会吃掉收益，此时退回固定配额加轻量优先级（仅按最近更新轮次轮转）更稳。部署上保持调度与训练解耦——rollout 引擎只读优先级队列、不改采样内核——是把这套机制引入现有 TensorRT-LLM/vLLM 栈的最低侵入路径，代价则集中在训练侧的归一化修正与队列版本管理上。</p>\n<h3 id=\"alg-rollout-bandit-scheduling-sec-7\">七 · 统计量的写入路径：从采样回传到后验</h3>\n<p>bandit 调度的第一步不是算分数，而是把每个 prompt 的历史统计维护成一份可增量更新的后验记录。调度器为 prompt 池中的每一项保存四元组：通过率 <span class=\"inline-math\">p_i</span>（该 prompt 上采样结果被判为正例的比例）、reward 方差 <span class=\"inline-math\">σ_i²</span>、平均生成长度 <span class=\"inline-math\">ℓ_i</span>、最近更新轮次 <span class=\"inline-math\">t_i</span>。这四项的输入是上一轮 rollout 引擎回传的逐条样本记录，输出是一条定长记录，写入代价极低——每条样本只贡献一次原子累加，不涉及任何张量运算。真正需要设计的是写入时机：若每条样本完成即写，调度器在解码高峰会被高频小写入打散；若整批回传后写，则后验滞后一整批。工程上的折中是按 rollout step 边界批量落盘，把一条 prompt 的 <span class=\"inline-math\">k</span> 条并行采样合并成一次更新，写入次数从 <span class=\"inline-math\">k</span> 降到 1，代价是同一 step 内新到达的样本要等到 step 结束才进入后验。</p>\n<p>reward 方差这一项不能直接用原始 reward 的二阶矩，因为 RL 中 reward 的尺度随训练漂移，绝对方差会把早期大 reward 的题目永久标记为高不确定性。可行做法是对 reward 做组内标准化后再取方差，即用同一 prompt 本轮 <span class=\"inline-math\">k</span> 条样本的均值做中心化，得到的是“组内离散度”，它与通过率一起构成信息增益的代理量：通过率接近 0.5 且组内离散度大的题目，梯度信号最强。平均生成长度 <span class=\"inline-math\">ℓ_i</span> 则是显存与带宽预算的输入——它直接决定该 prompt 在 KV cache 中占用的块数期望，调度器据此判断放大采样条数是否会把显存池撑爆。</p>\n<p>一个具体例子：池中某道数学题历史通过率 0.92、组内离散度极小、平均长度 380 token，另一道通过率 0.48、离散度大、平均长度 2100 token。前者写入后验后分数被压到接近下界，后者分数抬升；但后者 <span class=\"inline-math\">ℓ_i</span> 大，若本轮给它 16 条并行采样，KV 占用按 16×2100 token 估算，调度器必须在配额分配时把这一项计入，否则优先级排序会把显存推到 OOM 边缘。这就是统计量写入路径必须同时携带长度信息的原因：分数决定“值不值得采”，长度决定“采得起采不起”。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-8\">八 · 优先级打分：UCB 式信息增益上界的构造</h3>\n<p>拿到四元组后，调度器对每个 prompt 计算优先级分数。核心公式为</p>\n<div class=\"formula\">$$s_i=\\hat{\\mu}_i+c\\sqrt{\\frac{\\ln N}{n_i}}$$</div>\n<p>其中 <span class=\"inline-math\">\\(\\hat{\\mu}_i\\)</span> 是由通过率与 reward 方差估计的信息增益均值，<span class=\"inline-math\">n_i</span> 是该 prompt 已累计采样条数，<span class=\"inline-math\">N</span> 为总采样轮次，<span class=\"inline-math\">c</span> 控制探索强度。这一步的输入是上一步写好的后验，输出是一个标量分数数组，代价是一次 <span class=\"inline-math\">O(|P|)</span> 的逐元素计算，<span class=\"inline-math\">|P|</span> 为 prompt 池规模；对十万级池子，这是一次毫秒级的向量化运算，但若每 step 都全量重算，CPU 侧开销会与 GPU 侧解码时间形成竞争。因此实际实现常把打分拆成“全量粗排 + 局部精排”：粗排只在池子版本号变化时做，精排只对候选窗口内的若干 prompt 重算。</p>\n<p><span class=\"inline-math\">\\(\\hat{\\mu}_i\\)</span> 的构造决定分数的物理含义。若只取通过率，分数退化为“难题优先”，会把通过率 0.5 但梯度已饱和的题目长期占据算力；引入组内离散度后，<span class=\"hat\">μ</span> 可写成通过率与离散度的乘积或加权和，使得“通过率居中且样本分歧大”的题目得分最高。探索项 <span class=\"inline-math\">\\(c\\sqrt{\\ln N/n_i}\\)</span> 的作用是给采样条数少的 prompt 一个下限保护：新进入池子的题目 <span class=\"inline-math\">n_i</span> 小，根号项大，即便 <span class=\"inline-math\">\\(\\hat{\\mu}_i\\)</span> 暂时估计不准也能获得一次探测机会。这正是对抗训练早期统计稀疏的机制，但它只在 <span class=\"inline-math\">N</span> 增长慢于 <span class=\"inline-math\">n_i</span> 时有效；若 <span class=\"inline-math\">N</span> 随 step 快速膨胀，<span class=\"inline-math\">\\(\\ln N\\)</span> 的增长会压低探索项，调度过早收敛到 exploitation。</p>\n<p>代价层面要盯住两个量：一是打分频率与池子规模的乘积决定 CPU 侧延迟，二是分数排序后截断到配额窗口的排序代价 <span class=\"inline-math\">\\(O(|P|\\log|P|)\\)</span>。若池子规模上限受优先级队列重算开销约束，工程判断是给池子设硬上限并按最近更新轮次淘汰长期低分项，把 <span class=\"inline-math\">|P|</span> 控制在重算预算内，而不是让池子无限增长。一个具体例子：<span class=\"inline-math\">c</span> 取偏大值时，新题目的探测配额被抬高，若同时池中有一批通过率 0.5 的老题，排序结果会在两者间反复摆动，造成每 step 配额分配的抖动；把 <span class=\"inline-math\">c</span> 调小并给老题加一个“最近更新轮次”惩罚项，抖动被压住，代价是新题探测变慢。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-9\">九 · 配额分配：条数与 max_len 的联合放大</h3>\n<p>排序完成后进入配额分配。输入是分数有序队列与当前 step 的算力预算（GPU 秒、显存池余量、KV 块数），输出是每个 prompt 本轮的采样条数 <span class=\"inline-math\">k_i</span> 与最大生成长度 <span class=\"inline-math\">L_i</span>。这一步不是简单按分数比例切分，因为 <span class=\"inline-math\">k_i</span> 与 <span class=\"inline-math\">L_i</span> 是两个独立维度，且它们的代价结构不同：<span class=\"inline-math\">k_i</span> 放大增加并行序列数，主要吃 KV cache 容量与 decode 阶段的批内竞争；<span class=\"inline-math\">L_i</span> 放大延长单条序列，主要吃 decode 步数与带宽。高优先级 prompt 同时放大两者，是因为信息增益高的题目往往既需要更多样本估计方差、又需要更长生成长度才能暴露推理分歧。</p>\n<p>分配规则可写成按分数与方差的乘积做比例分配：<span class=\"inline-math\">\\(k_i \\propto s_i\\cdot \\mathrm{Var}[R|x_i]\\)</span>，再对 <span class=\"inline-math\">k_i</span> 做整数化与上下界裁剪（下界保证每组至少 1 条以维持 GRPO 组结构，上界防止单题垄断预算）。<span class=\"inline-math\">L_i</span> 的放大则要跟 <span class=\"inline-math\">ℓ_i</span> 挂钩：历史平均长度长的题目给更长 <span class=\"inline-math\">L_i</span>，但 <span class=\"inline-math\">L_i</span> 的增量要受 KV 块预算约束，因为一条 4096 token 的序列在 paged KV 下占用的块数是 512 token 序列的数倍。低优先级 prompt 的处理是减采样或整轮跳过，跳过的 prompt 不消耗任何 decode 步，这是省算力的主要来源。</p>\n<p>代价核算必须联合做：本轮总算力近似正比于 <span class=\"inline-math\">\\(\\sum_i k_i\\cdot L_i\\)</span>，而显存峰值近似正比于 <span class=\"inline-math\">\\(\\max_i k_i\\cdot L_i\\)</span> 加上在途批的驻留。一个具体例子：某 step 预算允许 4096 条并行序列，若把 60% 配额给 3 道高优先级题、每题 512 条、<span class=\"inline-math\">L_i</span> 放大到 3072，则这 3 题独占 1536 条序列且每条长序列的 KV 驻留远高于短题；剩余预算分给大量低优先级题时只能给到每组 1–2 条。这种极端倾斜在 decode 阶段会造成批内序列长度严重不均，连续批处理的调度器要额外做长度分桶，否则短题被长题拖住，单请求时延被拉长——而本机制明确以单位 FLOPs 的策略改进为 SLO，不以单请求时延衡量，所以这种时延退化是可接受的代价，但分桶开销仍要计入。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-10\">十 · 采样执行与回传：引擎侧的只读契约</h3>\n<p>配额下发后，rollout 引擎按优先级队列读取 <span class=\"inline-math\">(prompt, k_i, L_i)</span> 三元组并组织批。这一步的输入是配额表，输出是逐条样本的 token 序列与 reward 判定。关键设计约束是调度与训练解耦：引擎只读队列、不改采样内核，意味着采样内核仍然按统一的 temperature、top-p、KV 分页策略执行，bandit 只影响“采多少、采多长”，不影响“怎么采”。这样做的收益是引擎侧零侵入，代价是引擎无法针对高优先级题目做特殊解码优化（例如为长题单独开更大批），倾斜只能体现在配额数字上。</p>\n<p>执行侧的代价集中在两处。其一是批组织：同一 prompt 的 <span class=\"inline-math\">k_i</span> 条并行采样天然共享前缀，前缀 KV 只需算一次并复用，这是本机制能承受大 <span class=\"inline-math\">k_i</span> 的前提；若引擎不做前缀共享，<span class=\"inline-math\">k_i</span> 放大会线性放大预填代价。其二是回传粒度：样本完成后要把 reward、生成长度、是否正例写回调度器，回传本身是控制面流量，不占 GPU，但回传延迟决定后验更新滞后。工程上常把回传与 step 边界对齐，使后验在下一 step 开始前完成刷新。</p>\n<p>一个具体例子：某高优先级 prompt 本轮 <span class=\"inline-math\">k_i=32</span>、<span class=\"inline-math\">L_i=2048</span>，32 条序列共享同一段 600 token 前缀。预填阶段只算一次 600 token 的前缀 KV，32 条序列各自从第 601 token 开始 decode；若前缀不共享，预填代价按 32×600 计，在预填算力紧张的 step 会直接挤占其他题目的配额。回传时这 32 条样本的 reward 若高度一致（例如全部正确），组内离散度趋近 0，下一轮该题分数被压低，配额自动收缩——这就是回传驱动后验收缩的闭环。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-11\">十一 · 后验更新与周期性重算：算力迁移的时序</h3>\n<p>样本回传后，调度器更新四元组并重算分数。这里有一个时序选择：是每条样本回传即更新，还是整轮结束后统一重算。前者后验新鲜但重算频繁，后者重算便宜但存在滞后。机制描述中的“周期性重算”指向后者：调度器按固定 step 间隔（或按池子版本号变化）触发全量重算，把算力从已收敛题目迁移到新出现的高不确定性题目。输入是更新后的后验，输出是新的优先级队列，代价是一次全量打分加排序，与第二节的粗排同量级。</p>\n<p>滞后的代价必须显式建模。若某题在上一轮已收敛（通过率升到 0.95、离散度趋近 0），但队列尚未刷新，本轮仍按旧高分给它大配额，这部分算力就是纯浪费；反之新进入池子的高不确定性题目要等到下一次重算才被看见。滞后窗口的长度等于重算间隔，工程判断是把重算间隔与训练节奏匹配：重算太频繁则 CPU 开销吃掉收益，太稀疏则迁移不及时。可行的折中是“事件驱动 + 定时兜底”：当某题后验变化超过阈值（例如通过率跳变超过一定幅度）时立即触发该题重算，其余题目按定时全量重算。</p>\n<p>迁移的另一个代价是组内样本数不一致对训练侧的冲击。非均匀采样使同一 GRPO 组内样本条数不一致，若训练侧仍按固定组大小做 advantage 归一化，组内基线失真、梯度方差被放大。修正方式是按实际组大小做归一化，即 advantage 除以该组实际样本数而非名义组大小；这要求训练侧读取配额表或从样本元数据中恢复组大小，训练实现复杂度上升。一个具体例子：某题本轮只分到 1 条样本，其 advantage 无法做组内中心化，只能退化为单样本基线或直接跳过该组；若训练侧不识别这种退化组，会把单样本的高方差梯度灌进更新，造成策略抖动。因此配额分配的下界设 1 条只是维持组结构的最低要求，真正稳的做法是给“需要参与梯度更新”的题目设更高下界，把纯探测样本标记为不参与训练。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-12\">十二 · 失败模式在步骤链上的落点</h3>\n<p>把三个失败模式映射回步骤链，可以看出它们各自卡在不同环节。训练早期统计稀疏导致的伪高不确定性，落点在第一节的写入路径与第二节的打分：<span class=\"inline-math\">n_i</span> 极小时 UCB 根号项被偶然的高方差样本主导，分数虚高，配额被错配。缓解手段是在 <span class=\"inline-math\">n_i</span> 低于阈值时强制走均匀探测配额，不让 UCB 项单独决定排序；代价是早期若干 step 的算力分配接近随机，单位 FLOPs 改进暂时低于稳态。</p>\n<p>组内样本数不一致的梯度问题落点在第五节与训练侧接口：配额分配的整数化与上下界裁剪直接制造了不一致组，训练侧必须按组修正归一化。这一环节的代价是训练代码路径分叉——均匀采样路径与非均匀采样路径的 advantage 计算不同，两条路径的数值行为要在同一 step 内保持一致，否则同一批更新里混着两种归一化口径，梯度尺度失配。</p>\n<p>优先级队列重算滞后落点在第五节的时序：题目已收敛但队列未刷新时，算力仍按旧分数分配。这一失败模式不会报错，只会表现为单位 FLOPs 改进的缓慢下滑，因此需要监控“高分题目的实际 reward 离散度”这一指标——若某题持续拿大配额但组内离散度已趋近 0，说明队列滞后，应触发该题的单点重算。工程判断是：bandit 调度的收益上限由重算频率与池子规模共同决定，池子越大、重算越慢，滞后吃掉的信息增益越多；把池子按最近更新轮次分代、只对活跃代做高频重算，是控制这一代价的结构性手段。</p>\n<h3 id=\"alg-rollout-bandit-scheduling-sec-13\">十三 · 从“信息增益”到可计算的上界</h3>\n<p>把每个 prompt 的采样预算看成上下文 bandit 的一支臂，收益不是 reward 本身，而是这条样本对策略梯度的信息贡献。设 prompt $x$ 的真实信息增益均值为 $\\mu(x)$，采样 $n_x$ 条后得到经验估计 $\\hat\\mu(x)$。我们要的是在总采样轮次 $N$ 内，让 $\\sum_x n_x\\mu(x)$ 尽量大，同时必须为每个臂保留探索。UCB 的标准推导给出置信上界：若 $\\hat\\mu(x)$ 是 $n_x$ 个独立样本的均值，且单样本收益有界，则偏离真实均值的概率随 $n_x$ 增大按指数衰减，取对数后得到加性探索项 $\\sqrt{\\log N/n_x}$。于是</p>\n<div class=\"formula\">$$\\text{score}(x)=\\hat\\mu(x)+c\\sqrt{\\frac{\\log N}{n_x}}$$</div>\n<p>逐项读：$\\hat\\mu(x)$ 是“当前已知的利用价值”，$n_x$ 在分母上意味着采样越少的 prompt 探索项越大，$\\log N$ 让探索随总轮次缓慢增长而不爆炸，$c$ 是探索温度。关键一步不是这个式子本身，而是把 $\\hat\\mu$ 定义为<strong>由通过率与 reward 方差估计的信息增益</strong>：对二值通过率 $p_x$，单条样本的 Bernoulli 方差为 $p_x(1-p_x)$，它恰好在 $p_x\\to 0$ 或 $1$ 时趋零——这正是“已收敛题目”的数学特征；对连续 reward，用组内方差 $\\mathrm{Var}[R|x]$ 代替。因此 $\\hat\\mu(x)$ 不是 reward 均值，而是“这条 prompt 还能提供多少梯度信号”的代理量。第二式把配额与分数、方差同时绑定：</p>\n<div class=\"formula\">$$\\text{allocate}\\ n_x \\propto \\text{score}(x)\\cdot \\mathrm{Var}[R|x]$$</div>\n<p>方差项的作用是抑制“高分但已确定”的伪高价值：一个通过率 0.5、方差大的 prompt 分数高且值得多采；一个通过率 0.98、方差趋零的 prompt 即使 UCB 分数因 $n_x$ 小而虚高，乘上方差后配额也被压回去。这就是本机制与朴素 UCB 的分水岭——朴素 UCB 会把算力送给“采样少”的臂，而这里送给“采样少且仍有信息”的臂。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-14\">十四 · 推导的关键一步：为什么方差要乘在外面</h3>\n<p>从策略梯度的角度做一步展开。设组内归一化的 advantage 为 $\\hat A$，GRPO 类目标对一条样本的贡献近似正比于 $\\hat A^2$ 的期望，而 $\\mathbb{E}[\\hat A^2]$ 在组基线正确时正比于组内 reward 方差。也就是说，一条样本对参数更新的有效“功”是 $\\mathrm{Var}[R|x]$ 的函数，而不是 reward 的绝对值。把 UCB 的探索项理解为“对 $\\mu$ 的不确定性折价”，则单位算力期望增益近似为</p>\n<div class=\"formula\">$$\\frac{\\Delta J}{n_x}\\approx \\underbrace{\\left(\\hat\\mu(x)+c\\sqrt{\\tfrac{\\log N}{n_x}}\\right)}_{\\text{信息上界}}\\cdot\\underbrace{\\mathrm{Var}[R|x]}_{\\text{梯度杠杆}}\\cdot\\underbrace{\\frac{1}{\\bar L_x}}_{\\text{长度成本}}$$</div>\n<p>第三项 $\\bar L_x$ 是平均生成长度，它把“每条样本要花多少 token”折进来。这一步解释了为什么机制里高优先级 prompt 同时放大采样条数<strong>和</strong> max_len：长生成本身是成本，但对高方差题目，长生成往往正是暴露推理分叉的地方，单位 token 的信息密度更高，所以长度不是单纯的成本项而是与方差耦合的杠杆。工程上不必真去算 $\\Delta J$，只需保证排序时三个因子都进入分数，避免“只按条数排序、忽略长度成本”导致长题把队列吃满。</p>\n<p>代价随之而来：方差估计本身有噪声。$n_x$ 很小时 $\\mathrm{Var}[R|x]$ 的样本估计偏差大，乘在外侧会把噪声平方放大。这就是失败模式里“训练早期 UCB 分数被偶然高方差样本主导”的根源。缓解手段不是去掉方差项，而是给方差估计加收缩：$\\tilde{\\mathrm{Var}}=\\frac{n_x}{n_x+k}\\hat{\\mathrm{Var}}+\\frac{k}{n_x+k}\\bar{\\mathrm{Var}}_{\\text{pool}}$，$k$ 为收缩强度，把稀疏臂拉向池化先验。这一步在伪代码里必须显式出现，否则早期配额会抖。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-15\">十五 · 伪代码：从统计到配额队列</h3>\n<p>调度器与采样内核解耦，只维护一张优先级表并输出配额。下面给出可实现的结构，注意所有状态都是每 prompt 一份、按轮次增量更新。</p>\n<p>初始化：对池中每个 prompt $x$，置 $n_x\\leftarrow 0$，通过率 $p_x\\leftarrow 0.5$，方差 $\\sigma^2_x\\leftarrow \\bar\\sigma^2_{\\text{pool}}$，平均长度 $\\bar L_x\\leftarrow L_0$，最近更新轮次 $t_x\\leftarrow 0$。每轮 $t$：</p>\n<ul>\n<li>对每个 prompt 计算收缩后方差 $\\tilde\\sigma^2_x$，再由 $p_x$ 得 $\\hat\\mu_x=p_x(1-p_x)$（连续 reward 用 $\\tilde\\sigma^2_x$ 替代）。</li>\n<li>算分数 $s_x=\\hat\\mu_x+c\\sqrt{\\log(t+1)/\\max(n_x,1)}$，再算权重 $w_x=s_x\\cdot\\tilde\\sigma^2_x/\\bar L_x$。</li>\n<li>归一化 $w_x$ 得配额 $n_x^{\\text{new}}=\\max(1,\\ \\lfloor B\\cdot w_x/\\sum w \\rfloor)$，$B$ 为本轮总采样条数预算；对 $w_x$ 低于阈值的 prompt 置 0（跳过），但保留每 $K$ 轮一次的强制探测位以防饿死。</li>\n<li>按配额放大 max_len：$\\text{max\\_len}_x=L_{\\min}+\\alpha\\cdot\\tilde\\sigma^2_x$ 截断到上限，高方差题目拿更长生成长度。</li>\n<li>把 $(x,n_x^{\\text{new}},\\text{max\\_len}_x)$ 写入优先级队列，rollout 引擎按队列拉取，不改采样内核。</li>\n<li>采样回传后更新 $n_x\\leftarrow n_x+n_x^{\\text{new}}$，用增量式均值/方差更新 $p_x,\\sigma^2_x,\\bar L_x$，置 $t_x\\leftarrow t$。</li>\n<li>每 $T$ 轮全量重算一次分数并重排队列；两次重算之间只做增量插入，避免每轮 $O(|\\text{pool}|)$ 排序开销。</li>\n</ul>\n<p>这里有两个工程细节决定可实现性。其一，配额取整会引入残差，需把余数按最大余数法回填，否则总预算漂移。其二，增量方差更新用 Welford 形式，避免存全部历史 reward；每条 prompt 只留四个标量，显存开销可忽略，真正的开销是队列重算的 CPU 时间——池规模上千、每轮重排时，调度器本身会成为瓶颈，所以 $T$ 要按训练节奏选，而不是每步都重算。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-16\">十六 · 非均匀采样对训练侧的连带代价</h3>\n<p>配额非均匀后，同一 GRPO 组内样本条数不一致：高优先级 prompt 可能采 16 条，低优先级只采 2 条。若训练侧仍按固定组大小做 advantage 归一化，组基线 $\\bar R$ 的估计方差随组大小变化，小组成员少时基线噪声大，梯度方差被放大。修正方式是按组实际条数 $g_x$ 归一：$\\hat A_i=(R_i-\\bar R_x)/\\big(\\mathrm{std}(R_x)+\\epsilon\\big)$ 保持不变，但把该组的损失权重乘 $\\sqrt{g_x/g_{\\max}}$ 或按 $g_x$ 做无偏加权，使不同组对总梯度的贡献与其样本量匹配。这一步是训练侧复杂度的主要来源，也是本机制“调度与训练解耦”说法的边界：引擎解耦了，但优化器必须知道组大小。</p>\n<p>延迟与吞吐的账要算清楚：高优先级 prompt 拿更长 max_len，单条样本的解码步数上升，单请求时延变差；但 SLO 以单位 FLOPs 的策略改进衡量，所以允许时延换信息。风险在于批内长度方差变大，连续批处理下短样本先完成、长样本拖尾，批利用率下降。缓解是把同 max_len 档位的请求聚成一批，用分档批而非混批，代价是调度器多一层分桶逻辑。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-17\">十七 · 滞后与边界：队列刷新节奏决定有效性</h3>\n<p>优先级队列的周期性重算与引擎读取之间存在滞后。题目已收敛但队列未刷新时，算力仍按旧分数分配，迁移不及时。设重算周期 $T$、单轮 rollout 墙钟时间 $\\tau$，则滞后上界约 $T\\tau$；若训练进程在 $T\\tau$ 内已让某 prompt 的通过率从 0.5 升到 0.9，这段算力就是纯浪费。工程判断是让 $T$ 跟随“统计显著变化”而非固定步数：当某 prompt 的增量方差估计相对变化超过阈值时触发局部重排，全量重排仍按固定周期。这样把重算开销摊到真正需要迁移的题目上。</p>\n<p>适用边界由池规模与更新频率共同决定：池太大则全量重排的 CPU 开销压过 GPU 收益，池太小则 bandit 没有足够臂可探索；统计更新频率必须匹配训练节奏，更新太慢则分数失真，太快则方差估计噪声主导。数字锚点上，2026 年的部署形态里这套调度通常挂在分离式 rollout 服务前，作为优先级队列的一层，而不是嵌进采样内核——这正是它能与分页 KV、分块预填等机制共存的原因：它只决定“给谁多少条、多长”，不碰“怎么算”。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-18\">十八 · 边界、失效条件与系统代价：UCB 分配在真实 rollout 回路里的摩擦</h3>\n<p>把 <span>score</span> 公式落到工程上，第一处摩擦在 <span>n<sub>x</sub></span> 的分母语义。公式中 <span>n<sub>x</sub></span> 是该 prompt 的累计采样条数，<span>N</span> 是总采样轮次，探索项 <span>c√(log N / n<sub>x</sub>)</span> 随 <span>n<sub>x</sub></span> 增大而衰减，这意味着一个被反复采样的难题会自然降权——但降权速度取决于 <span>n<sub>x</sub></span> 的记账口径。若调度器按“本轮配额”而非“历史累计”更新 <span>n<sub>x</sub></span>，探索项会被周期性重置，同一批高方差题目被反复误判为新奇样本，算力在少数题目上振荡。可实现的修正是把 <span>n<sub>x</sub></span> 定义为带衰减的累计量 <span>n<sub>x</sub> ← λn<sub>x</sub> + k<sub>x</sub></span>（<span>k<sub>x</sub></span> 为本轮实际采样条数，<span>λ</span> 接近 1），使探索项单调收敛而非跳变；同时把 <span>N</span> 取为调度器全局轮次而非单 prompt 轮次，保证不同 prompt 的探索项可比。这一步决定了公式是“稳定收敛的分配器”还是“抖动的算力振荡器”。</p>\n<p>第二处摩擦是分配比例 <span>n<sub>x</sub> ∝ score(x)·Var[R|x]</span> 与 GRPO 组结构的冲突。GRPO 的 advantage 归一化默认组内样本数一致，而非均匀配额使同一 prompt 本轮采样条数在 <span>k<sub>min</sub></span> 与 <span>k<sub>max</sub></span> 之间浮动，组内均值与标准差的估计方差随 <span>k<sub>x</sub></span> 变化。若训练侧仍按固定组大小归一化，低配额组的基线失真、梯度方差被放大。工程上的做法是在 advantage 计算中显式携带 <span>k<sub>x</sub></span>，按组内实际条数做无偏归一化（分母用 <span>k<sub>x</sub>−1</span> 的样本标准差），并对 <span>k<sub>x</sub></span> 低于阈值的组直接跳过梯度贡献——这等价于承认“采样不足的组信息量不足”，与 bandit 的初衷一致，但把复杂度从调度器推到了训练侧。这是该方案最实的代价：调度与训练解耦只解耦了采样内核，没有解耦统计契约。</p>\n<p>第三处是滞后与稀疏。优先级队列周期性重算，rollout 引擎只读队列，两者之间存在一个重算周期的延迟；题目已收敛而队列未刷新时，算力仍按旧分数投放，迁移不及时。训练早期更严重：每个 prompt 历史样本极少，通过率与 reward 方差估计噪声大，UCB 分数被偶然的高方差样本主导，算力被错配到“伪高不确定性”题目——这些题目往往只是采样噪声大而非策略梯度大。边界条件因此可以写成两条工程判据：其一，<span>n<sub>x</sub></span> 低于某最小样本数时强制走均匀配额，不让 UCB 项主导排序；其二，重算周期必须与训练步节奏匹配，周期长于策略显著漂移的时间尺度即失效。下表把三类失效与对应代价并列：</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制根源</th><th>系统代价</th></tr></thead><tbody><tr><td>早期统计稀疏</td><td>Var[R|x] 由少数样本估计</td><td>算力错配到伪高方差题，单位 FLOPs 改进下降</td></tr><tr><td>组内条数不一致</td><td>非均匀配额与固定组归一化冲突</td><td>梯度方差放大、基线失真，训练侧需改归一化</td></tr><tr><td>队列刷新滞后</td><td>重算周期与策略漂移尺度不匹配</td><td>已收敛题继续占算力，迁移延迟一个周期</td></tr></tbody></table>\n<p>还有一个容易被忽略的容量约束：优先级队列重算开销随 prompt 池规模线性增长，池规模上限受重算频率约束——池越大，单次重算越慢，滞后越严重，形成“规模换精度”的负反馈。部署上应把重算做成增量式（只对统计量变化超过阈值的 prompt 重排），把全量重排降为低频后台任务。最终判断落在具体机制上：这套方案的收益不在公式本身，而在 <span>n<sub>x</sub></span> 的衰减记账、<span>k<sub>x</sub></span> 向训练侧的显式传递、以及增量重排三者是否同时到位；缺任一项，UCB 分配就会退化为按历史方差排序的静态启发式，失去随训练进程漂移而迁移算力的能力。</p>\n<h3 id=\"alg-rollout-bandit-scheduling-sec-19\">十九 · 负载配方：什么样的请求形态才吃得住这套调度</h3>\n<p>上下文 bandit 调度的负载配方不是“任意 RL rollout 都能套”，它有一套相当窄的匹配条件。请求形态上，它要求<strong>同一 prompt 的多条并行采样</strong>——因为信息增益的估计单位是 prompt，而不是单条序列；一个 prompt 只采一条，bandit 就没有组内方差可估，UCB 分数退化成纯通过率的贪心。长度分布上，它要求生成长度<strong>有可压缩的头部</strong>：高优先级 prompt 拿更长 max_len，低优先级 prompt 被减采样或跳过，前提是低优先级那部分生成长度确实短、确实不值得展开；如果池子里全是长链推理、每条都要顶到 max_len，那么“减采样”省下的只是条数，省不下单条序列的 KV 占用与解码步数，调度的杠杆立刻变钝。并发与批大小上，它要求批大小<strong>随优先级动态变化</strong>而不是钉死：高优先级 prompt 的采样条数与 max_len 同时放大，意味着这一批的 token 预算被少数 prompt 吃掉，连续批处理器的调度粒度必须允许“这一轮某 prompt 占 32 条、下一轮占 4 条”的剧烈抖动。</p>\n<p>把这三条写成可判定的配方条件：设 prompt 池为 $\\mathcal{P}$，每个 prompt $i$ 的采样条数 $n_i$ 与本轮 token 预算 $B$ 满足 $\\sum_i n_i \\cdot L_i \\le B$，其中 $L_i$ 是该 prompt 的 max_len。调度器解的是带约束的配额分配，而不是均分。一个具体例子：池中 512 个 prompt，其中约一成处于高不确定性区间，调度器给这五十余个 prompt 各分配数十条采样并把 max_len 抬到该任务的上限档，其余 prompt 压到个位数条数甚至本轮跳过；此时批内 token 分布极度偏斜，若引擎仍按固定 batch size 组批，要么显存被高优先级那批撑爆，要么低优先级那批凑不满、SM 空转。这就是“负载配方”必须先于“调度算法”确定的原因——算法只输出配额，能不能兑现配额是负载形态决定的。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-20\">二十 · 长度分布与批大小的耦合：max_len 放大是双刃剑</h3>\n<p>高优先级 prompt 同时获得更多条数与更长 max_len，这两件事在系统代价上完全不对称。加条数增加的是并行度，主要吃显存里的 KV 页与批内序列槽位；加 max_len 增加的是单条序列的解码步数与 KV 增长曲线，直接拉长该批的完成时间。在分页 KV 的引擎里，一条 max_len 被抬高的序列会在整个解码过程中持续占住页表项，且它的 KV 增长是单调的，中途无法回收——这跟“多来几条短序列”的代价结构完全不同。于是负载配方里必须有一条硬约束：<strong>单批内最长序列的 max_len 决定了这一批的尾部延迟</strong>，bandit 把 max_len 当奖励杠杆用时，等于在拿批完成时间换信息增益。</p>\n<div class=\"formula\">$$T_{\\text{batch}} \\approx \\max_{i \\in \\text{batch}} \\big(n_i^{\\text{step}} \\cdot \\tau_{\\text{decode}}\\big) + T_{\\text{prefill}},\\quad \\text{s.t.}\\ \\sum_i n_i L_i \\le B_{\\text{KV}}$$</div>\n<p>公式的含义很直白：批完成时间由批内步数最多的那条序列主导，而 KV 预算约束的是条数与长度的乘积。bandit 若只盯着“给高优先级 prompt 加 max_len”，就会把 $T_{\\text{batch}}$ 推到由少数难题决定，低优先级 prompt 即使只需几步也被拖着等——吞吐被尾部吃掉。工程判断是：max_len 的放大应当<strong>分级而非连续</strong>，按任务的长度档位（短/中/长）跳档，而不是按 UCB 分数线性外推；条数的放大可以连续，长度的放大必须离散，否则批内长度方差会把连续批处理的收益抹平。一个反例形态：池中长度分布是重尾的，少数 prompt 天然要生成长度上限，bandit 又把它们的 max_len 再抬一档，结果每批都被这几条拖着跑满，单位 FLOPs 的策略改进反而下降——这正是“负载不对”的第一种表现。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-21\">二十一 · 负载不对时的三种塌陷</h3>\n<p>第一种塌陷是<strong>统计稀疏期的伪高不确定性</strong>。训练早期每个 prompt 的历史样本极少，通过率与 reward 方差估计噪声大，UCB 分数里的探索项 $c\\sqrt{\\ln N / n_i}$ 对 $n_i$ 极敏感，偶然采到的一条高方差样本就能把某个 prompt 的分数顶到队列头部。此时算力被错配到“看起来难、其实只是没采够”的题目上，真正的难题因为恰好早先采过几条、方差被低估而排到后面。系统代价是：这一轮大量 token 花在伪难题的长生成上，KV 占用抬高、批完成时间拉长，而策略改进几乎为零。负载配方对此的应对不是调 $c$，而是设<strong>最小采样条数下限</strong>：任何 prompt 在被纳入 bandit 排序前先保证一个基础采样数，让 $\\hat\\mu_i$ 有最低限度的支撑，否则 UCB 只是在拟合噪声。</p>\n<p>第二种塌陷是<strong>非均匀采样撞上固定组归一化</strong>。GRPO 的 advantage 归一化默认组内样本数一致，bandit 把组大小打散后，若训练侧仍按固定组大小算基线与方差，组内基线失真、梯度方差被放大。这不是调度器的错，是负载配方与训练配方的接口没对齐：调度输出的是“每 prompt 采样条数向量”，训练侧必须按<strong>实际组大小</strong>做归一化，且要处理组大小为 1 的退化情形（此时组内方差无定义，只能退化为单样本基线或直接丢弃该组）。代价体现在训练稳定性上：单位 FLOPs 的策略改进被梯度噪声抵消，调度省下的算力又被训练侧的方差放大吐回去。</p>\n<p>第三种塌陷是<strong>队列重算滞后</strong>。优先级队列周期性重算，rollout 引擎读取的是上一版队列；题目已收敛但队列未刷新时，算力仍按旧分数分配。滞后窗口内，高优先级那批 prompt 的采样被重复投入已无信息量的题目，而新出现的高不确定性题目还没进队列。系统代价是迁移不及时造成的算力空转，量级取决于重算周期与训练节奏的比值——周期越长，滞后越大；周期越短，重算本身的开销（对全池重算 UCB 分数并排序）就越频繁地打断 rollout。负载配方在这里的约束是：<strong>prompt 池规模与统计更新频率必须匹配训练节奏</strong>，池子越大，全量重算越贵，越需要增量更新或分层重算。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-22\">二十二 · 配方判定：四条可检查的负载特征</h3>\n<p>把“适合什么请求形态”落成可检查的特征，比讲原则有用。第一条，<strong>组内可采样的并行度</strong>：同一 prompt 能否并行发出多条请求而不被引擎的并发上限卡住；若引擎按请求数限流而非按 token 预算限流，高优先级 prompt 的条数放大直接撞限流墙，配额兑现不了。第二条，<strong>长度分布的头部厚度</strong>：低优先级 prompt 的平均生成长度是否显著低于高优先级，若是，减采样与跳过才真正省算力；若长度分布平坦，bandit 只剩条数一个杠杆。第三条，<strong>批内长度方差</strong>：连续批处理在长度方差大时收益下降，bandit 放大 max_len 会进一步推高方差，负载配方需评估引擎是否支持按长度分桶或分块预填来吸收这个方差。第四条，<strong>统计更新延迟容忍度</strong>：训练一步的 wall-clock 与队列重算周期之比，决定滞后塌陷的严重程度。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>匹配时的表现</th><th>不匹配时的塌陷</th><th>系统代价落点</th></tr></thead><tbody><tr><td>组内并行度充足</td><td>条数配额可兑现</td><td>撞并发限流，配额作废</td><td>吞吐、SM 空转</td></tr><tr><td>长度分布头部厚</td><td>减采样真省算力</td><td>只省条数不省步数</td><td>解码步数、KV 增长</td></tr><tr><td>批内长度方差可控</td><td>批完成时间不被尾部拖死</td><td>尾部延迟主导批</td><td>批延迟、显存峰值</td></tr><tr><td>重算周期匹配训练节奏</td><td>算力迁移及时</td><td>旧分数持续分配算力</td><td>单位 FLOPs 改进下降</td></tr></tbody></table>\n<p>一个具体判定例子：池规模中等、长度分布重尾、引擎按 token 预算组批且支持分块预填——这组特征下 bandit 调度能兑现配额，长度方差被分块预填吸收一部分，重算开销可承受；反过来，池规模极大、长度分布平坦、引擎按请求数限流——三条全不匹配，此时上 bandit 调度只会把算力错配放大，不如退回按前缀局部性的固定调度。这就是负载配方的工程含义：它先于算法决定这套调度值不值得上。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-23\">二十三 · 配额兑现的接口：优先级队列要带什么字段</h3>\n<p>负载配方最终要落成一个队列条目，队列里带什么字段决定了引擎能不能按配方兑现。至少需要：prompt 标识、本轮采样条数 $n_i$、max_len 档位（离散档而非连续值）、优先级分数（用于排序与调试）、以及该 prompt 的统计新鲜度标记（最近更新轮次）。新鲜度标记是应对滞后塌陷的关键——引擎读到条目时可以判断这条配额是否过期，过期则回退到保守配额而不是照旧放大。伪代码思路：</p>\n<div class=\"formula\">$$\\text{for } i \\in \\text{top-}k(\\text{queue}):\\ \\text{issue}(i,\\ n_i,\\ \\text{len\\_tier}_i);\\ \\text{else } \\text{issue}(i,\\ n_{\\min},\\ \\text{base\\_tier})$$</div>\n<p>即只有排序靠前的 prompt 拿到放大配额，其余一律回退到最小条数与基础长度档。这样即使队列滞后，最坏情况也只是“该放大的没放大”，而不是“该收缩的还在放大”——把滞后塌陷的代价从“算力错配到已收敛题目”降级为“算力未及时迁移”，后者对策略改进的伤害小得多。系统代价上，这个接口让引擎不必理解 bandit，只读三个字段；代价是调度器必须维护排序与新鲜度，重算开销落在调度侧而非 rollout 侧，与“调度与训练解耦”的部署配方一致。</p>\n<p>配额兑现还有一条隐性约束：<strong>条数放大与 max_len 放大不能同时线性叠加</strong>。若某 prompt 同时拿到数倍条数与最高长度档，它的 KV 占用是两者的乘积，单这一条就能吃掉整批预算，把其他 prompt 挤出批。负载配方应规定放大预算的上界：单 prompt 的 KV 占用不超过批预算的固定比例，超出则先砍条数、再降长度档。这是把“算力集中到高不确定性样本”从口号变成可执行配额的最后一步——没有这个上界，bandit 的排序再准，批也会被一条难题撑爆。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-24\">二十四 · 负载配方：bandit 调度吃什么样的请求分布</h3>\n<p>这套方案对请求形态有明确偏好：同一 prompt 的多条并行采样、批大小随优先级动态伸缩、高优先级 prompt 的采样条数与 max_len 同时放大。它天然适合“题目池规模中等、每题可重复采样、通过率与 reward 方差能被稳定估计”的 RL rollout 负载，SLO 也应以单位 FLOPs 的策略改进衡量，而非单请求时延。若负载是长短混杂的一次性请求、每题只采一条、或 prompt 池大到统计更新跟不上训练节奏，bandit 后验就退化为噪声源——此时固定按长度或前缀局部性调度反而更稳。规模上限直接受优先级队列重算开销约束：重算周期必须与训练步节奏匹配，队列越长、重算越频繁，调度器自身占用的 CPU 与同步开销越不可忽略。</p>\n<p>失效条件集中在三处。其一，训练早期每个 prompt 的历史样本极少，通过率与 reward 方差估计噪声大，UCB 分数被偶然的高方差样本主导，算力被错配到伪高不确定性题目；此时 $c\\sqrt{\\ln N/n_i}$ 的探索项远大于 $\\hat\\mu_i$，排序几乎等同于随机，应临时退回均匀采样或按长度分层。其二，非均匀采样使同一 GRPO 组内样本条数不一致，若仍按固定组大小做 advantage 归一化，组内基线失真、梯度方差被放大，训练侧必须按组实际样本数修正归一化，这层实现复杂度是方案落地的隐性代价。其三，优先级队列周期性重算与 rollout 引擎读取之间存在滞后，题目已收敛但队列未刷新时算力仍按旧分数分配，迁移不及时，表现为高优先级槽位被“已无信息量”的题目长期占据。</p>\n<p>负载不对时的系统代价可直接量化到资源面。设第 $i$ 题分配采样条数 $n_i$、平均生成长度 $L_i$，则本轮 rollout 的 token 预算为 $\\sum_i n_i L_i$；bandit 调度把 $n_i$ 与 max_len 同时放大到高方差题目上，若估计失真，这部分预算就变成纯浪费的显存与解码带宽占用，KV cache 峰值随最长 max_len 抬升，连续批处理的有效批大小被少数长样本拖低，吞吐与单位 FLOPs 改进同时下滑。一个具体例子：某批 prompt 中多数题目通过率已接近饱和、方差趋零，bandit 应将其减采样或跳过，把配额让给新出现的高方差题目；若队列滞后未刷新，这些饱和题仍按旧高分占用采样条数与长 max_len，rollout 引擎的批内 token 分布被拉长，解码阶段显存压力上升而策略改进近乎为零——这正是固定长度调度失效模式的镜像，只是换成了“分数过期”的形式。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>适配判断</th><th>不对时的代价</th></tr></thead><tbody><tr><td>同 prompt 多条并行采样</td><td>适配，方差可估</td><td>单条采样下方差噪声主导排序</td></tr><tr><td>批大小随优先级动态变化</td><td>适配，配额可迁移</td><td>固定批大小下高低优先级互相挤占</td></tr><tr><td>统计更新频率匹配训练节奏</td><td>适配，后验可信</td><td>队列滞后，算力滞留于已收敛题</td></tr><tr><td>组内样本数一致</td><td>需按组修正归一化</td><td>基线失真，梯度方差放大</td></tr></tbody></table>\n<h3 id=\"alg-rollout-bandit-scheduling-sec-25\">二十五 · 硬件档位：按优先级分层而不是按峰值选型</h3>\n<p>bandit 调度的部署配方第一件事不是选最强的卡，而是承认优先级分布本身是分层的。调度器输出的优先级队列天然呈长尾：头部少量 prompt 拿到数倍采样条数与更长 max_len，尾部大量 prompt 被减采样甚至跳过。把这两类负载塞进同一档硬件是浪费——头部需要的是大 batch 下的高吞吐 GEMM 与足够 TMEM 容纳长序列注意力，尾部需要的是极低单位成本地跑完短样本。可复现的做法是两档：主档用 B200/GB200 NVL72 承载高优先级队列，配 FP8 或 NVFP4 权重与 KV；辅档用同代但更小规模的切片承载低优先级与探测性采样。两档共享同一优先级队列格式，调度器只写队列，引擎按档位标签取任务，采样内核零改动。</p>\n<p>代价落在带宽与功耗上：高优先级档位把 max_len 拉长后，KV 带宽成为主约束，单条样本的 HBM 读写量随长度线性上升，而算力利用率反而被注意力主导；低优先级档位则是典型的 decode 受限，SM 占用低、功耗低但吞吐密度高。工程判断是：不要用同一套并行拓扑硬扛两种形态，档位划分的收益大于单卡峰值差异。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-26\">二十六 · 并行拓扑：让优先级决定 TP/EP 而不是让模型决定</h3>\n<p>常规推理按模型宽度定 TP，bandit 场景要反过来：高优先级 prompt 的采样条数被放大，等效 batch 变大，此时 TP 过大会把一次前向切得过碎，跨卡 all-reduce 延迟摊薄不了；TP 过小则单卡放不下长 max_len 的 KV。可复现配方是给高优先级档位一个较小的 TP（配合 EP 承载 MoE 专家）与较大的 DP，让放大后的 batch 在 DP 维度铺开，把通信压到 NVLink 域内；低优先级档位用更激进的 TP 换取单样本低延迟，因为它的 batch 本来就小。</p>\n<div class=\"formula\">$$\\text{throughput} \\approx \\frac{B_{\\text{eff}}\\cdot L_{\\text{gen}}}{t_{\\text{prefill}} + t_{\\text{decode}}(B_{\\text{eff}}, \\text{TP})},\\quad B_{\\text{eff}} = n_i \\cdot b_{\\text{base}}$$</div>\n<p>其中 $n_i$ 是该 prompt 本轮分到的采样条数，$b_{\\text{base}}$ 是基础批。这个式子说明：把 $n_i$ 放大到 TP 不匹配的拓扑上，$t_{\\text{decode}}$ 里的通信项会随 TP 线性增长而吃掉落收益。具体例子：某数学题 prompt 历史 reward 方差高，调度器给到 8 倍采样条数，若拓扑仍是 TP=8 的单请求形态，8 条样本被切成 8 个微批串行，等效吞吐不升反降；改成 TP=2、DP=4 后 8 条样本并行铺开，NVLink 5 域内 all-reduce 次数下降，decode 阶段才真正吃到放大 batch 的红利。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-27\">二十七 · 量化方案：优先级分层对应精度分层</h3>\n<p>NVFP4 在 Blackwell 上的收益集中在权重与激活的带宽节省，但它的数值稳定性对长生成尾部敏感——这一点在别处已展开，此处只取结论：高优先级 prompt 往往伴随更长 max_len 与更高 reward 方差，尾部 token 的 logprob 偏差会直接污染 bandit 的方差估计，让下一轮优先级判断失真。可复现配方因此做精度分层：高优先级档位权重走 FP8、KV 走 FP8 并保留关键层的更高精度；低优先级与探测性采样走 NVFP4，用带宽换样本量。分层的关键是让量化档位成为优先级队列的一个字段，而不是全局开关。</p>\n<p>代价是显存与带宽的权衡：FP8 KV 相比 NVFP4 每 token 占用翻倍，长 max_len 下 KV 池容量直接决定并发上限；但高优先级样本数量少，翻倍后的绝对占用可控。反过来，低优先级样本用 NVFP4 把单位样本显存压到最低，才能在辅档上堆出足够样本量喂给 bandit 后验。工程判断：量化档位跟着优先级走，比全局统一精度更省，也比全局高精度更稳。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-28\">二十八 · KV 策略：按优先级分配池容量与驻留时长</h3>\n<p>bandit 调度让同一 prompt 的多条采样共享前缀，这是 KV 复用的天然入口，但复用策略要跟优先级绑定。高优先级 prompt 本轮被反复采样，其前缀 KV 值得常驻并跨轮保留，因为下一轮它大概率仍在头部；低优先级 prompt 前缀 KV 用短 TTL 或直接不驻留，避免挤占池容量。可复现做法是给优先级队列加一个 KV 驻留等级字段：头部 prompt 走常驻池并配前缀共享，中部走按轮次回收，尾部走即用即弃。</p>\n<p>代价直接体现在池容量与命中率上：常驻池被头部 prompt 占满时，新出现的高不确定性题目拿不到 KV 空间，调度器算出的高优先级反而落不了地。因此驻留等级要设上限，按“头部 prompt 数 × 平均前缀长度”预留，剩余容量留给迁移进来的新题。具体例子：某代码题 prompt 连续三轮处于头部，其前缀 KV 常驻后每轮省掉重复预填；第四轮它通过率收敛、优先级掉出头部，驻留等级自动降级，容量释放给刚被重算进头部的新题——这个迁移动作与优先级重算同周期触发，避免队列滞后导致的容量僵化。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-29\">二十九 · 调度参数：c、重算周期与组内归一化的联动</h3>\n<p>可复现配置的核心是三个参数的联动：探索强度 $c$、优先级重算周期 $T$、以及 GRPO 组内样本数修正策略。$c$ 过大时 UCB 分数被 $\\sqrt{\\ln N/n_i}$ 项主导，训练早期 $n_i$ 极小，分数被偶然高方差样本拉爆，算力错配到伪高不确定性题目；$c$ 过小则新题拿不到探测配额，收敛题持续占坑。配方建议按训练阶段分段设 $c$：早期用较小 $c$ 抑制噪声主导，统计密度上来后放大 $c$ 鼓励探索。</p>\n<div class=\"formula\">$$\\text{quota}_i = \\text{clip}\\Big(\\frac{s_i}{\\sum_j s_j}\\cdot Q_{\\text{total}},\\ n_{\\min},\\ n_{\\max}\\Big),\\quad \\text{adv}_g = \\frac{R - \\bar{R}_g}{\\sigma_g\\sqrt{1/n_g}}$$</div>\n<p>第二式是训练侧的必配项：非均匀采样让同一 GRPO 组内样本条数 $n_g$ 不一致，若仍按固定组大小归一化，基线 $\\bar{R}_g$ 与方差 $\\sigma_g$ 都被扭曲，梯度方差被放大。可复现做法是把实际 $n_g$ 写进 advantage 分母，并在组内样本过少时回退到跨组基线。重算周期 $T$ 与训练步节奏对齐：$T$ 太短则队列重算开销吃掉调度收益，$T$ 太长则收敛题占坑、迁移滞后。代价是队列重算的 CPU 开销与 rollout 引擎读取的同步延迟，规模上限受此约束——prompt 池越大，单次重算越贵，$T$ 被迫拉长，滞后风险上升。</p>\n<p>具体例子：一个混合难度池，早期 $c$ 取小值、$T$ 取与若干训练步对齐，头部 prompt 的 $n_i$ 被放大到基础批的数倍并同步拉长 max_len；采样回传后统计量更新，下一周期重算把已收敛题降级、把新进高方差题升级。整个链路里 rollout 引擎只读队列与档位标签，采样内核不动，训练侧只多了一个按 $n_g$ 修正的归一化分支——这是把 bandit 调度落进生产的最小改动面。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-30\">三十 · 配方落地时的三条硬边界：统计冷启动、组内基线失真与队列滞后</h3>\n\n<p>这套部署配方真正难的不是把 UCB 分数算出来，而是让它在<strong>统计稀疏、组内非均匀、队列滞后</strong>三种状态下不崩。先看冷启动：bandit 后验的置信半径项 $c\\sqrt{\\ln N/n_i}$ 在 $n_i$ 很小时会急剧放大，训练早期每个 prompt 只有个位数样本，$\\hat\\mu_i$ 由通过率与 reward 方差估计而来，方差估计本身在 2–3 条样本上几乎没有自由度，一个偶然失败的长样本就能把该 prompt 的分数顶到队列头部。工程上的做法是给每个 prompt 设一个<strong>最小采样地板</strong> $n_{\\min}$（例如先跑满一个 GRPO 组大小的均匀配额），在 $n_i&lt;n_{\\min}$ 阶段强制走均匀调度、不读 UCB 分数，只有当统计量跨过地板后才进入 bandit 模式；同时把 $c$ 做成随训练轮次衰减的调度量而非常数，早期大 $c$ 保证覆盖、后期小 $c$ 收紧到 exploitation。代价是明确的：冷启动阶段算力按均匀分配走，等于放弃了一部分早期信息增益，且地板值设大了会让整个 bandit 收益被摊薄，设小了噪声直接穿透到配额层。</p>\n\n<p>第二个边界是 GRPO 组内样本数不一致。bandit 给高优先级 prompt 分配更多采样条数与更长 max_len，同一 prompt 的组大小从固定 $G$ 变成 $G_i$，而 advantage 归一化若仍按全局或固定组均值减、组标准差除，组内基线就被污染：一个被放大到 $2G$ 的难题组，其组内均值更接近真实通过率，而一个被削减到 $G/2$ 的简单组基线方差更大，两组梯度尺度不可比。修正思路是把归一化写成按组自适应的形式，$$\\hat A_{i,j}=\\frac{R_{i,j}-\\bar R_i}{\\sigma_i+\\epsilon}\\cdot\\sqrt{\\frac{G}{G_i}}$$，其中 $\\sqrt{G/G_i}$ 是对组大小的方差补偿项，$\\bar R_i,\\sigma_i$ 只在本组内统计。这一步把训练侧实现复杂度推高：采样内核不改，但 advantage 计算、梯度累积的 batch 拼装、以及可能的 token-level loss 归一化都要感知 $G_i$。系统代价体现在训练吞吐上——非均匀组使得一个 micro-batch 内序列长度分布更散，padding 与负载不均衡让 GPU 利用率下降，长 max_len 的高优先级样本还会拉高单步显存峰值。</p>\n\n<p>第三个边界是优先级队列的重算与读取之间的滞后。调度器周期性重算分数，rollout 引擎只读队列、不改内核，这带来一个结构性延迟：题目已经收敛（通过率接近 1、方差趋零），但队列尚未刷新，算力仍按旧分数灌给这些题。滞后窗口 $\\Delta t$ 与重算开销直接冲突——重算要遍历整个 prompt 池、更新统计、排序，池规模越大单次重算越贵，于是 $\\Delta t$ 被迫拉长，迁移越不及时。适用边界就在这里：prompt 池规模与统计更新频率必须匹配训练节奏，规模上限受队列重算开销约束。可用的缓解手段是分层刷新——对分数变化率高的 prompt 做高频局部重算，对已收敛 prompt 只做低频确认，把全量排序降为增量堆维护；代价是调度器状态机变复杂，且增量维护在并发回传下需要加锁或做无锁快照，否则统计量与配额读取会出现撕裂。</p>\n\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发信号</th><th>系统代价</th><th>缓解手段</th></tr></thead><tbody><tr><td>统计冷启动</td><td>$n_i$ 低于地板、方差估计自由度不足</td><td>早期算力错配到伪高不确定性题</td><td>均匀地板 + 衰减 $c$</td></tr><tr><td>组内非均匀</td><td>$G_i$ 偏离基准组大小</td><td>梯度方差放大、padding 浪费、显存峰值抬升</td><td>按组归一化 + $\\sqrt{G/G_i}$ 补偿</td></tr><tr><td>队列滞后</td><td>已收敛题仍占高配额</td><td>算力迁移不及时、单位 FLOPs 改进下降</td><td>分层增量刷新 + 快照读取</td></tr></tbody></table>\n\n<p>把这三条边界合起来看，配方是否可复现取决于一个判断：<strong>bandit 的收益必须大于它引入的方差与调度开销</strong>。在 prompt 池小、训练轮次短、reward 信号本身噪声大的场景里，均匀调度加固定组大小反而更稳；bandit 调度真正划算的是池子足够大、统计更新频率跟得上训练节奏、且训练侧愿意承担按组归一化的实现成本。落地时建议把优先级队列做成可关闭的旁路：先以均匀配额跑通全链路，再打开 bandit 并只对通过率与方差都跨过阈值的 prompt 生效，用单位 FLOPs 的策略改进作为唯一验收指标，而不是单请求时延。</p>\n<h3 id=\"alg-rollout-bandit-scheduling-sec-31\">三十一 · 显存：非均匀配额如何把峰值推到采样侧</h3>\n<p>bandit 调度把采样条数与 max_len 同时放大到高优先级 prompt 上，显存代价因此不再是“批大小 × 平均序列长度”的平滑函数，而由本轮被选中的少数重仓 prompt 决定。一个 prompt 若拿到 k 条并行采样、max_len 抬到 L，则其 KV 占用近似为 k·L·(2·H_kv·d_head·层数)·字节数，其中 H_kv 为 KV 头数。分页 KV 与连续批处理能把碎片压下去，但压不住这条乘积：k 与 L 是同向放大的，二者相乘是二次效应，而普通调度里 k 固定、L 随请求走，峰值是线性的。工程上的直接后果是 rollout 引擎的显存水位由优先级队列头部几个 prompt 支配，尾部低优先级 prompt 即使被跳过也省不出多少空间。</p>\n<p>更麻烦的是生成长度的动态性。bandit 给高优先级 prompt 更长 max_len，本意是让高不确定性题目多探索几步，但实际生成长度分布长尾，少数样本会吃满 max_len。若引擎按 max_len 预留 KV 页，预留量按 k·L 计，实际占用却按真实长度计，预留与占用之间的差额在重仓 prompt 上被放大成不可回收的预留碎片。可行做法是把 max_len 的放大做成阶梯而非连续值，并让分页分配器按块粒度惰性增长，把“预留”换成“按需”，代价是解码步的页表查找开销上升，属于用带宽换显存。</p>\n<p>具体例子：同一批次里 prompt A 被分到 16 条采样、max_len 抬到上限，prompt B 只分到 2 条、max_len 压到短档。A 的 KV 需求约为 B 的数十倍，整批的显存峰值几乎完全由 A 决定；此时把 B 再减半采样对峰值无贡献，真正有效的是对 A 的 k 与 L 做联合上限约束，例如规定 k·L 不超过某阈值，超出则拆成两个微批错峰执行。这条约束应写进调度器的配额分配，而不是留给引擎事后 OOM 回退。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-32\">三十二 · 带宽：权重读取被摊薄，KV 读写被集中</h3>\n<p>解码阶段的显存带宽消耗分两块：每步读取权重，以及每步读写 KV。前者与批内 token 数近似无关（权重读取量固定），后者与批内并发序列数成正比。bandit 调度把并发序列集中到少数 prompt 上，权重读取被更多 token 摊薄，这是好事；但 KV 读写量随 k 上升，且高优先级 prompt 的长 max_len 让每条序列的 KV 更长，单步 KV 带宽占比上升。设批内并发序列数为 B_eff、平均上下文长度为 L_eff，则单步 KV 带宽近似正比于 B_eff·L_eff，而权重带宽为常数 W。当 B_eff·L_eff 增长快于算术强度允许的范围，解码从带宽受限滑向更严重的带宽受限，token 间延迟（ITL）被拉长。</p>\n<div class=\"formula\">$$\\text{ITL} \\approx \\frac{W + \\kappa\\cdot B_{\\text{eff}}\\cdot L_{\\text{eff}}}{\\text{HBM 带宽}},\\qquad \\text{吞吐} \\approx \\frac{B_{\\text{eff}}}{\\text{ITL}}$$</div>\n<p>这里 κ 是每 token 每层 KV 字节数的聚合系数。公式的含义很直白：吞吐的分子是并发数，分母里却含并发数与长度的乘积，所以盲目抬高 k 会在某个点之后让吞吐掉头向下。bandit 调度天然倾向于抬高 k，必须给 k 设一个由带宽模型反推的上界，而不是让 UCB 分数无约束地换算出配额。</p>\n<p>具体例子：某轮调度把三个高优先级 prompt 各分到大批量采样，B_eff 翻倍而 L_eff 因长 max_len 也上升，ITL 明显变长；此时若 SLO 以单位 FLOPs 的策略改进衡量，长 ITL 本身不违规，但 rollout 墙钟时间被拉长，训练侧等待变久，等效于降低了整条流水线的样本产出率。调度器需要把“墙钟产出率”作为配额的第二约束，与信息增益分数一起做排序后的可行性裁剪。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-33\">三十三 · 通信：并行采样把集合通信从稀疏推向密集</h3>\n<p>同一 prompt 的多条并行采样在张量并行组内是同步解码的，k 条序列一起走 TP 的 all-reduce，通信量与 k 成正比而计算量也与 k 成正比，看似无害；真正的代价出现在专家并行（EP）与流水并行（PP）场景：k 条序列的 token 在 EP 下被路由到不同专家，all-to-all 的负载均衡依赖各专家收到的 token 数接近，而 bandit 调度让少数 prompt 独占大量序列，这些序列的 token 分布高度同质，容易在路由上形成热点专家，all-to-all 出现长尾。PP 场景下则表现为微批数量随 k 变化，流水气泡比例随微批变小而上升。</p>\n<p>跨节点层面，rollout 引擎与训练侧的梯度/样本回传走的是另一条链路。bandit 调度让每轮采样条数不均匀，回传的样本张量尺寸随轮次波动，集合通信的缓冲区分档若按固定尺寸配置，就会出现小轮次浪费带宽、大轮次触发重分配的双向损耗。工程判断是把回传做成按优先级分组的变长打包，让通信量与实际采样条数对齐，代价是接收侧需要做不定长拼接，训练侧的输入管线要能吃变长 batch。</p>\n<p>具体例子：一轮里高优先级 prompt 的 k 被抬到很大，其 token 在 EP 路由上集中到少数专家，all-to-all 的完成时间由最慢的那条链路决定，整批解码被这条链路拖住；而同一轮的低优先级 prompt 几乎不产生通信。这种“通信量高度不均”是 bandit 调度的结构性特征，不能靠调大 all-to-all 缓冲区解决，只能靠对单 prompt 的 k 设上限、并把同质 token 的路由打散（例如在配额分配时对同一 prompt 的采样做微批切分，让不同微批落在不同调度窗口）。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-34\">三十四 · 功耗与热：算力集中带来的局部热点</h3>\n<p>bandit 调度把算力集中到少数 prompt，GPU 的利用率曲线从“均匀中载”变成“少数 SM 满载、其余空闲”的脉冲形态。脉冲形态对功耗的影响有两面：平均功耗可能下降（空闲 SM 拉低均值），但瞬时功耗与 di/dt 应力上升，供电与散热的裕度按峰值设计，机柜级功率封顶（power capping）一旦触发，会把满载 SM 的时钟压下来，恰好压在被重仓的高优先级 prompt 上，造成“越重要的活越先被降频”的反直觉结果。</p>\n<p>GB200/GB300 NVL72 这类机柜级系统里，功率封顶是机柜粒度的，单卡降频会通过 NVLink 域内的同步解码传导到同组其他卡。bandit 调度若把重仓 prompt 集中在一个 TP 组上，该组的功耗峰值就成为整个机柜的约束点。缓解手段是把高优先级配额在时间上错峰、在空间上分散到多个 TP 组，让峰值不叠加；代价是调度器需要维护每个 TP 组的功耗预算视图，把配额分配变成带功耗约束的装箱问题，重算开销上升。</p>\n<p>具体例子：某轮调度把全部高优先级 prompt 塞进同一组 GPU，机柜功率触及封顶，时钟下调，这组 GPU 上的长 max_len 采样被拉长，墙钟时间反而比均匀调度更差；把同样的配额拆到两组、错开半个窗口执行，峰值减半、总墙钟缩短。这说明功耗约束必须进入配额分配的目标函数，而不是事后监控。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-35\">三十五 · 尾延迟：优先级队列滞后与组内不一致的叠加</h3>\n<p>bandit 调度的尾延迟来源不是单请求的 P99，而是“本轮最慢的那条重仓采样”。高优先级 prompt 拿到更长 max_len，其单条采样天然落在长尾；同时优先级队列周期性重算与引擎读取之间存在滞后，题目已收敛但队列未刷新时，算力仍按旧分数分配，这些“过期重仓”样本既占显存又拖长尾。更隐蔽的是非均匀采样导致的 GRPO 组内样本数不一致：若训练侧仍按固定组大小做 advantage 归一化，梯度方差被放大、组内基线失真，表现为策略改进的方差变大，而不是单步变慢——这类代价不出现在 rollout 的延迟指标里，却出现在训练收敛曲线上。</p>\n<p>尾延迟的量化可以写成：本轮墙钟 ≈ max over 被选 prompt of (k_i 条采样的完成时间)，而单条完成时间随 max_len 增长。若把 k_i 与 L_i 同时放大，max 的期望随二者乘积上升，尾延迟对配额分配极其敏感。工程上的做法是给“本轮墙钟”设硬上限，把配额分配变成在墙钟约束下最大化总信息增益的背包问题，高优先级 prompt 若单条就逼近上限，则减少其 k 而不是减少其 L——因为 L 决定单条时长，k 决定并行度，二者对墙钟的贡献不同。</p>\n<p>具体例子：两个高优先级 prompt 分数接近，一个通过率低、方差大（信息增益高但单条采样可能很长），另一个方差中等但历史生成长度短。按分数排序会把前者排在前面并给足 k 与 L，本轮墙钟由它决定；若改为按“单位墙钟信息增益”排序，后者可能更优，因为它在同样墙钟内能贡献更多有效样本。这把 UCB 分数从“绝对信息增益”改成“信息增益除以预估墙钟”，是调度器在本规模下必须做的修正。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-36\">三十六 · 规模上去以后哪里先崩</h3>\n<p>把 prompt 池从数千扩到数十万，最先崩的不是 GPU 算力，而是优先级队列的重算开销与统计新鲜度。每个 prompt 维护通过率、reward 方差、平均生成长度、最近更新轮次，周期性全量重算的复杂度随池规模线性上升，而重算频率需匹配训练节奏；池子一大，重算周期被拉长，队列滞后加剧，过期重仓的比例上升，尾延迟与显存峰值同时恶化。第二崩的是统计稀疏：池子大意味着每个 prompt 的历史样本更少，UCB 分数被偶然的高方差样本主导，算力被错配到伪高不确定性题目，这是训练早期失败模式在规模上的放大版。</p>\n<p>第三崩的是通信与功耗的耦合：池子大、TP 组多，高优先级配额在组间的分布决定了机柜功率峰值与 all-to-all 热点，调度器若只按分数排序而不看组级预算，规模一上来就会出现局部封顶与链路长尾同时发生。可行的分层是：顶层按组做粗粒度配额（受功耗与通信预算约束），组内按 UCB 分数做细粒度分配，重算只做增量更新而非全量，把 O(池规模) 的重算降到 O(变化量)。</p>\n<p>具体例子：池规模扩大后，全量重算从每轮一次降到每若干轮一次，期间新出现的难题得不到配额、已收敛的旧题继续占算力，表现为单位 FLOPs 的策略改进斜率变缓；把重算改为按“统计量变化超过阈值”触发增量更新，并给新 prompt 一个探索配额下限，斜率恢复。这里的工程判断是：bandit 调度的规模上限不由 GPU 决定，而由“统计更新频率能否跟上训练节奏”决定，配额分配的正确性在规模上比分配速度更稀缺。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-37\">三十七 · 规模上去以后，先崩的是队列重算与组内归一化</h3>\n<p>把 bandit 调度推到万级 prompt 池，最先触顶的不是 GPU 算力，而是调度器的 CPU 侧开销。每轮重算要对全部 prompt 遍历一遍 UCB 分数并排序，代价随池规模线性增长、随重算频率线性增长；而 rollout 引擎读取优先级队列与调度器写入之间存在滞后窗口。题目已收敛、队列未刷新时，算力仍按旧分数分配，迁移不及时——这不是精度问题，是调度周期与训练步节奏失配的结构性问题。规模上限因此由“优先级队列重算开销 × 刷新频率”约束，而非由采样内核决定。</p>\n<p>第二个崩点是显存与带宽的非均匀化。高优先级 prompt 同时放大采样条数与 max_len，单批内序列长度方差急剧变大，KV cache 的分配从“按批均值预留”退化为“按最长序列预留”，显存碎片与浪费同步上升。设批内第 $i$ 个请求长度为 $L_i$、采样条数为 $k_i$，则批级 KV 占用近似为</p>\n<div class=\"formula\">$$M_{\\text{KV}} \\approx \\sum_i k_i L_i \\cdot 2 \\cdot n_{\\text{layer}} \\cdot d_{\\text{head}} \\cdot n_{\\text{kv}} \\cdot b_{\\text{bytes}}$$</div>\n<p>放大 $k_i$ 与 $L_i$ 是乘性叠加，长尾请求会把整批的显存水位抬到按均值估算的数倍，continuous batching 的填充效率随之下降，尾延迟由最长的那条采样决定。</p>\n<p>第三个崩点在训练侧。非均匀采样使同一 GRPO 组内样本条数不一致，若仍按固定组大小做 advantage 归一化，组内基线失真、梯度方差被放大。修正方式是分组归一化：对组 $g$ 用实际样本数 $n_g$ 而非名义组大小，$$\\hat{A}_j = \\frac{R_j - \\bar{R}_g}{\\sigma_g + \\epsilon},\\quad \\bar{R}_g = \\frac{1}{n_g}\\sum_{j=1}^{n_g} R_j$$，并对 $n_g$ 低于阈值的组降权或丢弃。这一步把调度自由度换成了训练实现的复杂度，是本方案最实在的代价。</p>\n<table class=\"mini\"><thead><tr><th>规模阶段</th><th>先崩的资源</th><th>表现</th></tr></thead><tbody><tr><td>池规模扩大</td><td>调度 CPU 与队列滞后</td><td>旧分数继续分配算力，迁移不及时</td></tr><tr><td>采样非均匀化</td><td>KV 显存与批内带宽</td><td>按最长序列预留，填充率下降、尾延迟抬升</td></tr><tr><td>组内条数不一致</td><td>训练侧归一化正确性</td><td>基线失真、梯度方差放大</td></tr></tbody></table>\n<p>工程判断：bandit 调度的收益上限由“信息增益估计的信噪比”决定，而系统代价由“非均匀性”决定。两者在规模上反向走——池越大、统计越稀疏，UCB 分数越容易被偶然高方差样本主导，算力错配到伪高不确定性题目；同时非均匀批带来的显存与归一化代价越重。可行的边界做法是把重算频率与训练步绑定、对 $k_i$ 设上限以约束批内长度方差、并在训练侧强制按实际组大小归一化，把调度自由度限制在系统能吸收的范围内。</p>\n<h3 id=\"alg-rollout-bandit-scheduling-sec-38\">三十八 · 精度漂移：UCB 分数被噪声主导的早期失败</h3>\n<p>bandit 调度的第一个失败模式不在 rollout 引擎，而在统计量的可信度上。调度器为每个 prompt 维护通过率 $\\hat{p}_i$、reward 方差 $\\hat{\\sigma}_i^2$ 与已采样条数 $n_i$，三者共同决定信息增益均值 $\\hat{\\mu}_i$。训练早期 $n_i$ 普遍是个位数，$\\hat{\\sigma}_i^2$ 的抽样误差与 $\\hat{p}_i$ 的二项噪声同时放大，UCB 分数 $s_i=\\hat{\\mu}_i+c\\sqrt{\\ln N/n_i}$ 的探索项虽然随 $n_i$ 减小而增大，却无法区分“真的没采过”与“偶然采到一条高方差样本”。结果是一批伪高不确定性题目被推上优先级队列顶端，获得成倍的采样条数与更长的 max_len，而真正需要采样的题目排在后面。</p>\n<p>诊断这类问题的抓手是分数分解：把 $s_i$ 拆成均值项与探索项分别打点，观察高优先级 prompt 的均值项是否长期停留在初始先验附近。若某个 prompt 连续若干轮排名靠前但 $\\hat{\\mu}_i$ 几乎不动，说明它靠的是探索项而非真实信息增益，属于统计稀疏导致的错配。工程上的修法是给 $\\hat{\\mu}_i$ 加收缩：用池化先验把单 prompt 的方差估计向全局方差拉近，等价于伪计数 $\\alpha,\\beta$ 的二项后验，使早期分数由先验主导、随 $n_i$ 增长逐步让位于观测。代价是收敛速度：收缩过强会让真正的高方差题目也被压低，单位 FLOPs 的策略改进在中期反而下降。监控指标应同时看“高优先级集合的 $\\hat{\\mu}_i$ 更新幅度”与“被跳过 prompt 的后续通过率”，前者衡量分数是否在动，后者衡量错配是否在纠正。</p>\n<div class=\"formula\">$$\\hat{\\mu}_i^{\\text{shrunk}}=\\frac{n_i\\hat{\\mu}_i+\\kappa\\mu_0}{n_i+\\kappa},\\quad \\kappa\\ \\text{为收缩强度，}\\mu_0\\ \\text{为池化先验均值}$$</div>\n<p>具体例子：某轮调度后排名前十的 prompt 中有六个的 $n_i$ 仍小于先验伪计数，其分数几乎完全由 $\\sqrt{\\ln N/n_i}$ 决定。把这六个的采样配额减半、把配额转给 $n_i$ 已过阈值但方差仍高的 prompt，下一轮高优先级集合的均值项更新幅度明显上升，说明算力开始落到有信息量的题目上。这类调整不触碰采样内核，只改调度器的先验参数。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-39\">三十九 · OOM 与批抖动：max_len 放大带来的显存非线性</h3>\n<p>高优先级 prompt 同时获得更多采样条数与更长 max_len，这两项在显存上不是线性叠加。批内 KV cache 占用正比于 $\\sum_j L_j$（各序列实际生成长度之和），而分页分配下每个序列还要按块向上取整，块内碎片随序列数增加而累积。当调度器把一批高优先级 prompt 的 max_len 从基准值抬到上限，实际生成长度分布的长尾被拉长，单批 KV 峰值可能远超按平均长度估算的值，触发 OOM 或迫使引擎中途抢占（preemption）重算。</p>\n<p>批抖动的表现形式是吞吐的锯齿：某一轮因 OOM 触发抢占，被抢占序列的 KV 被换出或丢弃，重算时又占满显存，下一轮再次触发。诊断要看三个量：单批 KV 峰值与预算的比值、抢占次数、以及被抢占序列的平均已生成长度。若被抢占序列的已生成长度普遍偏长，说明长尾序列在挤占短序列的空间，调度器应按 max_len 分档而不是统一放大。工程修法是给优先级配额加显存预算约束：把本轮总 KV 需求写成 $\\sum_i n_i \\cdot \\mathbb{E}[L_i|\\text{max\\_len}_i]$ 的估计，超过预算时按优先级从低到高削减条数，而不是削减 max_len——削减 max_len 会截断高价值样本，削减条数只损失重复采样。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>正常区间特征</th><th>异常特征</th><th>处置</th></tr></thead><tbody><tr><td>单批 KV 峰值/预算</td><td>随轮次平稳波动</td><td>贴近预算且锯齿</td><td>按 max_len 分档配额</td></tr><tr><td>抢占次数</td><td>偶发、短序列</td><td>连续多轮、长序列</td><td>显存预算前置约束</td></tr><tr><td>批内序列长度方差</td><td>低</td><td>长尾拉长</td><td>长短序列分池调度</td></tr></tbody></table>\n<p>具体例子：某轮把高优先级 prompt 的 max_len 统一抬升后，批内长度方差翻倍，KV 峰值触及预算上限并触发抢占；改为按 prompt 的历史平均生成长度分两档、只对长档放大 max_len，短档保持基准，峰值回落到预算内且抢占消失，吞吐锯齿随之消失。代价是长档的批大小受限，单轮采样条数略降，但被截断的样本数为零。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-40\">四十 · 路由不均：优先级队列与引擎读取的滞后</h3>\n<p>调度与训练解耦的代价是队列滞后。调度器周期性重算优先级，rollout 引擎按批读取队列；两次重算之间，题目可能已经收敛，但队列里的旧分数仍把它排在前列，算力继续按旧分数分配。滞后在路由上表现为不均：一部分引擎实例持续拿到高优先级的长序列请求，另一部分实例的队列被低优先级短请求填满，实例间负载与显存占用出现系统性偏差。更隐蔽的是迁移不及时——调度器本应把算力从已收敛题目迁到新出现的高不确定性题目，但新题目进入队列要等下一次重算，迁移窗口被拉长。</p>\n<p>诊断要区分“队列滞后”与“引擎消费不均”。前者看队列中高优先级条目的分数年龄（距上次重算的轮次），后者看各实例的队列深度与平均 max_len 的离散度。若分数年龄集中在重算周期的后半段且实例间 max_len 离散度大，说明滞后已传导到路由。修法有二：其一，把重算周期与训练步对齐，在每次策略更新后立即重算，使分数年龄不超过一个训练步；其二，引擎读取队列时按实例的显存余量做二次分配，把长档请求优先派给余量大的实例，短档请求填满其余实例。代价是二次分配引入调度器与引擎之间的额外往返，重算频率提高也增加优先级队列的计算开销，规模上限受此约束。</p>\n<div class=\"formula\">$$\\text{lag}_i = t_{\\text{now}} - t_{\\text{last\\_recalc}}(i),\\quad \\text{route\\_skew}=\\frac{\\max_k \\bar{L}_k - \\min_k \\bar{L}_k}{\\overline{\\bar{L}}}$$</div>\n<p>具体例子：某引擎集群中两个实例的平均 max_len 相差明显，分数年龄在重算周期末段集中升高；把重算对齐到训练步并把长档请求按显存余量二次派发后，实例间 max_len 离散度收敛，被跳过的低优先级 prompt 在新一轮重算后进入队列，迁移窗口缩短到一个训练步。这里不涉及采样内核改动，只改队列刷新节奏与派发规则。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-41\">四十一 · 尾延迟尖刺：非均匀采样的组内失衡</h3>\n<p>非均匀采样使同一 GRPO 组内样本条数不一致，这是调度机制的直接后果，也是尾延迟尖刺的来源之一。高优先级 prompt 获得更多采样条数，其组内样本多、单组完成时间由最长的那条序列决定；低优先级 prompt 条数少，组完成快。若训练侧按固定组大小做 advantage 归一化，组内基线失真，梯度方差被放大，表现为训练损失尖刺；若引擎按组聚合结果再回传，组完成时间被最长序列拖住，尾延迟尖刺出现在聚合端而非单请求端。诊断要把“单请求尾延迟”与“组聚合尾延迟”分开看：前者由长序列决定，后者由组内条数不均衡决定。</p>\n<p>修法是按组修正归一化：组内基线用该组实际样本数 $n_g$ 计算，advantage 的方差估计除以 $n_g$ 而非固定组大小，使不同条数的组在梯度上可比。引擎侧则对组聚合设软超时，超时后先回传已完成样本、剩余样本异步补齐，避免单条长序列拖住整组。代价是异步补齐使组内样本到达训练侧的时间不一致，需要训练侧支持部分组更新或延迟聚合；软超时阈值设得过紧会丢弃有效样本，设得过松则尾延迟尖刺依旧。</p>\n<div class=\"formula\">$$\\hat{A}_{g,j}=\\frac{R_{g,j}-\\bar{R}_g}{\\hat{\\sigma}_g/\\sqrt{n_g}},\\quad n_g\\ \\text{为该组实际采样条数}$$</div>\n<p>具体例子：某轮高优先级组的条数是低优先级组的多倍，聚合端等待最长序列导致组完成时间拉长；改为组内基线按 $n_g$ 修正并对聚合设软超时后，已完成样本先回传，尾延迟尖刺从聚合端消失，训练损失的尖刺幅度也随之收敛。这里的关键判断是：尾延迟尖刺的根因在组内条数不均衡，而不在单条序列的生成长度，削减 max_len 治不了它。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-42\">四十二 · 监控面与回滚：把失败模式映射到可观测信号</h3>\n<p>上述四类失败模式需要一张统一的监控面，把调度器的内部量与引擎的外部量对齐。调度侧打点：每个 prompt 的 $\\hat{\\mu}_i$、$n_i$、分数年龄、本轮配额与被跳过标记；引擎侧打点：单批 KV 峰值、抢占次数、批内长度方差、实例间 max_len 离散度、组聚合尾延迟。两侧用 prompt id 关联，才能把“分数错配”追到“显存峰值”或“尾延迟尖刺”。监控的判据不是单点阈值，而是配对关系：高优先级集合的均值项更新幅度低且分数年龄高，指向精度漂移；KV 峰值贴近预算且抢占连续，指向 OOM 与批抖动；实例间 max_len 离散度大且分数年龄集中在周期末段，指向路由不均；组内条数方差大且聚合尾延迟高，指向组内失衡。</p>\n<p>回滚要按失败模式分级，而不是整体回退到固定调度。精度漂移的回滚是调高收缩强度 $\\kappa$、把探索系数 $c$ 暂时压低，让分数由观测主导；OOM 与批抖动的回滚是关闭 max_len 放大、恢复按长度分档的配额；路由不均的回滚是把重算周期缩回一个训练步并暂停二次派发；组内失衡的回滚是恢复固定组大小归一化并放宽聚合软超时。每级回滚都只改调度器参数或队列规则，不动采样内核，因此可以在训练不中断的情况下切换。回滚的触发条件应与监控判据绑定：连续若干轮同一判据越界才触发，单轮越界只记录不动作，避免参数在噪声下反复抖动。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>主判据</th><th>回滚动作</th><th>代价</th></tr></thead><tbody><tr><td>精度漂移</td><td>高优先级均值项不更新、分数年龄高</td><td>调高 $\\kappa$、压低 $c$</td><td>中期收敛变慢</td></tr><tr><td>OOM/批抖动</td><td>KV 峰值贴预算、连续抢占</td><td>关闭 max_len 放大、按长度分档</td><td>长档批大小受限</td></tr><tr><td>路由不均</td><td>实例 max_len 离散度大、分数年龄集中</td><td>重算对齐训练步、暂停二次派发</td><td>重算开销上升</td></tr><tr><td>组内失衡</td><td>组内条数方差大、聚合尾延迟高</td><td>恢复固定组归一化、放宽软超时</td><td>梯度方差回升</td></tr></tbody></table>\n<p>具体例子：某轮监控发现高优先级集合的均值项连续多轮不动、分数年龄接近重算周期上限，同时 KV 峰值贴预算。按分级回滚先调高 $\\kappa$ 并压低 $c$，分数开始随观测更新，高优先级集合换血；KV 峰值随之回落，因为伪高不确定性题目不再获得成倍条数。两级回滚都只改调度器参数，采样内核与引擎配置未动，训练未中断。这里落在具体机制上的工程判断是：回滚粒度必须与失败模式的根因对齐，整体回退会同时丢掉调度带来的算力节省，分级回滚只牺牲对应维度的收益。</p>\n<h3 id=\"alg-rollout-bandit-scheduling-sec-43\">四十三 · 同族算法的谱系与选择维度</h3>\n<p>rollout 上下文 bandit 调度不是孤立存在的。与它同处\"采样预算分配\"这一层的算法，至少包括四类：按 prompt 长度或前缀局部性做静态分桶的规则调度、按课程学习（curriculum）由易到难推进的阶段式调度、按在线剪枝在解码中途丢弃低价值样本的运行时调度，以及本文讨论的按历史 reward 统计做 UCB 式动态配额的上下文 bandit 调度。它们共享同一个目标函数——单位 FLOPs 的策略改进——但作用于流水线的位置不同：规则调度决定\"谁进入批次\"，课程调度决定\"何时进入批次\"，剪枝决定\"何时退出批次\"，bandit 调度决定\"给多少条数与多长 max_len\"。选择算法的第一步不是比较优劣，而是确认瓶颈落在哪个环节。</p>\n<p>选择维度可以收敛为四个可测量量：其一，样本价值是否随训练进程漂移。若漂移显著（通过率随策略更新快速爬升），静态分桶必然把算力钉死在已收敛题目上，此时 bandit 的后验更新是必需的；若漂移缓慢（如固定难度的评测型 rollout），规则调度的排序开销更低。其二，统计可得性。bandit 依赖每个 prompt 的历史通过率与 reward 方差，若单 prompt 历史样本数长期停留在个位数，UCB 的置信项主导分数，估计噪声会盖过真实信息增益。其三，组内一致性约束。GRPO 一类算法要求同组样本数一致以做基线归一化，非均匀采样会破坏这一前提，需要训练侧按组修正 advantage。其四，调度开销占端到端时延的比例。优先级队列重算与引擎读取之间的滞后，在短 rollout（生成长度小、轮次密）场景下会被放大。</p>\n<p>把这四个维度做成决策表，比记住某个算法的名字更有用。表中\"适用\"一列不是绝对判断，而是\"在该条件下该算法的边际收益最大\"。</p>\n<table class=\"mini\"><thead><tr><th>算法族</th><th>作用位置</th><th>核心信号</th><th>适用条件</th><th>主要代价</th></tr></thead><tbody><tr><td>规则/分桶调度</td><td>批次准入</td><td>prompt 长度、前缀局部性</td><td>样本价值漂移慢、统计稀疏</td><td>算力错配到简单题</td></tr><tr><td>课程式调度</td><td>阶段推进</td><td>全局通过率阈值</td><td>难度分层清晰、池子稳定</td><td>阈值切换滞后、阶段边界抖动</td></tr><tr><td>在线剪枝</td><td>解码中途</td><td>逐步置信度/熵</td><td>长生成、早期可判废</td><td>剪枝误判损失有效样本</td></tr><tr><td>上下文 bandit</td><td>配额分配</td><td>历史 reward 方差、通过率</td><td>漂移显著、单 prompt 统计充足</td><td>早期噪声、组内样本不均</td></tr></tbody></table>\n<p>一个具体例子：某 RL 训练池中 60% 的 prompt 在若干轮后通过率接近饱和，剩余 40% 长期低通过率且 reward 方差大。规则调度按长度分桶，会把长 prompt 持续排进批次，但长 prompt 未必是难题；bandit 调度则会把配额从饱和组迁向高方差组，代价是训练侧要接受组内样本数不一致。若该池子的 prompt 难度分布稳定、几乎不漂移，bandit 的收益就退化为排序开销，规则调度反而更稳。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-44\">四十四 · 与在线剪枝的边界：分配前 vs 分配后</h3>\n<p>在线剪枝与 bandit 调度常被混为一谈，因为两者都在\"减少无效算力\"。区别在于作用时序：bandit 在采样开始前决定配额，剪枝在解码过程中决定是否继续。前者改变的是\"进入解码的样本条数与 max_len\"，后者改变的是\"已进入解码的样本何时终止\"。二者可以叠加，但叠加时的交互必须显式建模，否则会出现预算被双重削减。</p>\n<p>设 bandit 给某 prompt 分配 <span>n</span> 条采样、每条 max_len 为 <span>L</span>，在线剪枝在解码第 <span>t</span> 步以概率 <span>p_t</span> 终止。则该 prompt 的期望解码 token 数为 <span>n·Σ_{t≤L} p_t</span>（<span>p_t</span> 为存活概率）。若 bandit 已按信息增益把 <span>n</span> 压到很低，再叠加激进剪枝，实际有效样本数可能低于 GRPO 组基线所需的最小条数，梯度估计方差反而上升。工程判断是：当 bandit 配额已低于组最小样本数时，关闭该组的剪枝，或把剪枝阈值放宽，保证基线可估。</p>\n<div class=\"formula\">$$\\text{score}(x) = \\hat\\mu(x) + c\\sqrt{\\frac{\\log N}{n_x}},\\quad \\text{allocate}\\ n_x \\propto \\text{score}(x)\\cdot \\mathrm{Var}[R|x]$$</div>\n<p>上式中的 <span>Var[R|x]</span> 项是 bandit 与剪枝分工的关键。bandit 用方差估计信息增益，方差大的 prompt 获得更多条数；剪枝则在单条内部用逐步置信度削减长度。若把两者都交给同一个信号（例如都用 reward 方差），会出现信号复用：高方差 prompt 既拿更多条数又被允许更长生成，算力集中度超出预算。合理做法是让 bandit 管条数、剪枝管长度，两个维度各自有独立的预算上限。</p>\n<p>系统代价上，剪枝的收益体现在解码阶段的显存带宽与 KV cache 占用——提前终止释放的 KV 块可被后续请求复用；bandit 的收益体现在批次构成——把低价值 prompt 移出批次直接降低预填与解码的总 token 数。前者是\"单请求内省\"，后者是\"跨请求重排\"。在分离式预填/解码部署中，bandit 影响的是预填队列的排序，剪枝影响的是解码队列的驻留时间，两者的调度器若不在同一控制面，滞后会叠加。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-45\">四十五 · 与课程式调度的取舍：全局阈值 vs 逐 prompt 后验</h3>\n<p>课程式调度用一个全局通过率阈值把 prompt 池切成\"当前可训练\"与\"暂缓\"两段，随训练推进移动阈值。它的优点是实现极简、组内样本天然一致（同一阶段内所有 prompt 用相同条数），缺点是阈值是标量，无法表达同一阶段内不同 prompt 的信息增益差异。bandit 调度则是逐 prompt 的后验，表达力强但破坏了组内一致性。</p>\n<p>取舍可以用一个判据：池内信息增益的离散度。若同一阶段内各 prompt 的 reward 方差差异小（难度分层清晰、同层内几乎同质），全局阈值已经足够，bandit 的逐 prompt 排序只带来开销；若同层内差异大（例如同一长度桶里既有已饱和题又有高方差题），阈值调度会把两者同等对待，bandit 才有边际收益。判据的测量方式是统计同层内 reward 方差的变异系数，变异系数高则选 bandit。</p>\n<p>课程调度的另一个隐性代价是阈值切换的滞后：阈值移动后，新进入的 prompt 需要重新积累统计，而移出的 prompt 可能仍有残余信息量。bandit 的周期性重算同样有滞后（失败模式中已列），但滞后粒度是单 prompt 而非整层，迁移更细。工程上常见的折中是\"分层 bandit\"：先用课程阈值粗分阶段，再在阶段内用 bandit 做配额微调，组内一致性通过阶段内固定最小条数来保底。</p>\n<p>具体例子：一个数学推理 rollout 池，按难度分为三档，每档内通过率方差差异明显。纯课程调度在档内平均分配条数，导致档内已饱和题占用配额；分层 bandit 在档内把配额迁向高方差题，同时保留每档的最小条数以满足 GRPO 基线。代价是调度器需要维护\"档—prompt\"两级统计，重算开销高于单级阈值，但低于全池逐 prompt 重排。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-46\">四十六 · 与分页 KV、前缀共享的耦合条件</h3>\n<p>bandit 调度改变的是采样条数与 max_len，这两个量直接作用于 KV cache 的分配形态。分页 KV 批量 rollout 与前缀 KV 共享这两个条目的机制此处不展开，只讲耦合点：bandit 给高优先级 prompt 放大条数与 max_len 时，同一 prompt 的多条采样共享前缀，前缀 KV 只算一次，后续分支各自分页。若 bandit 把条数放大到超过分页池的单请求配额上限，前缀共享的收益会被分页碎片抵消。</p>\n<p>耦合条件是\"条数放大倍数\"与\"前缀共享率\"的乘积。设前缀长度为 <span>P</span>、分支平均长度为 <span>B</span>、条数为 <span>n</span>，无共享时 KV 量为 <span>n(P+B)</span>，有共享时为 <span>P+nB</span>。bandit 放大 <span>n</span> 时，共享带来的节省比例随 <span>n</span> 增大而趋近 <span>P/(P+B)</span> 的上限，但分页池的块粒度决定了实际可共享的连续性。若前缀被切成多块且分支起点不对齐块边界，共享率下降，bandit 的条数放大反而推高显存峰值。</p>\n<p>工程判断：当 bandit 配额把某 prompt 的条数放大到超过前缀共享的经济阈值（即 <span>nB</span> 超过单请求分页配额）时，应把该 prompt 拆成多个子批次分批采样，而不是一次性放大条数。拆分保持了前缀共享的对齐，代价是调度器需要感知分页池的剩余块数，把\"配额分配\"与\"显存可用量\"联合排序。这一步把 bandit 从纯统计调度变成统计加资源的联合调度，是部署配方中调度与训练解耦之外必须补上的一环。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-47\">四十七 · 决策表：给定条件下的算法选择</h3>\n<p>把前四节的判据落成一张可执行的决策表。表的输入是四个可测量条件，输出是首选算法与必须接受的代价。条件之间不独立，实际选型时按行优先级从上到下匹配，命中即停。</p>\n<table class=\"mini\"><thead><tr><th>条件组合</th><th>首选</th><th>次选/叠加</th><th>必须接受的代价</th></tr></thead><tbody><tr><td>漂移慢 + 单 prompt 统计稀疏</td><td>规则/分桶</td><td>课程阈值</td><td>算力错配到饱和题</td></tr><tr><td>漂移快 + 单 prompt 统计充足 + 组内一致性可放宽</td><td>上下文 bandit</td><td>在线剪枝管长度</td><td>组内样本不均、训练侧归一化修正</td></tr><tr><td>漂移快 + 组内一致性硬约束</td><td>分层 bandit</td><td>阶段内固定最小条数</td><td>两级统计重算开销</td></tr><tr><td>长生成 + 早期可判废</td><td>在线剪枝</td><td>bandit 管条数</td><td>剪枝误判、双重削减风险</td></tr><tr><td>前缀共享率高 + 分页池紧张</td><td>bandit + 子批次拆分</td><td>前缀对齐块边界</td><td>调度器需感知显存余量</td></tr></tbody></table>\n<p>一个具体匹配过程：某 Agent 协同 rollout 池，prompt 来自多轮工具调用轨迹，通过率随训练快速爬升，单 prompt 历史样本数已达数十条，GRPO 组大小可放宽。按表命中第二行，选上下文 bandit 管条数，叠加在线剪枝管长度，训练侧按组修正 advantage。若该池子的分页池余量长期紧张，则再叠加第五行的子批次拆分，把条数放大改为分批，避免显存峰值。</p>\n<p>反向匹配同样重要：若某池子的 reward 方差变异系数低、漂移慢，却因为\"bandit 听起来更先进\"而选它，结果是排序开销换不来配额收益，且训练侧被迫承担组内归一化的复杂度。选型的纪律是先用变异系数与漂移速率两个标量做粗筛，再决定是否引入后验更新。</p>\n\n<h3 id=\"alg-rollout-bandit-scheduling-sec-48\">四十八 · 选型后的接口与滞后预算</h3>\n<p>选定算法之后，剩下的是接口与滞后预算。bandit 调度与 rollout 引擎的接口只有一个优先级队列：引擎读取队列、按配额采样、回传统计量。接口的契约必须明确三件事：队列的重算周期、引擎读取的时效、统计回传的批次粒度。重算周期与训练节奏匹配是适用边界的一部分；读取时效决定滞后；回传粒度决定后验更新的噪声。</p>\n<p>滞后预算可以用一个简单的不等式约束：设重算周期为 <span>T_r</span>、引擎读取延迟为 <span>T_l</span>、统计回传延迟为 <span>T_b</span>，则从\"题目已收敛\"到\"配额真正下调\"的总滞后为 <span>T_r+T_l+T_b</span>。若该滞后超过题目从高方差到收敛的平均轮次，配额迁移就永远追不上漂移，bandit 退化为滞后指标。工程判断是把 <span>T_r</span> 压到漂移时间尺度的三分之一以内，并把 <span>T_l</span> 做成引擎侧的本地缓存读取而非跨进程查询。</p>\n<p>与相邻算法的对照最终落在一个工程判断上：bandit 调度的价值不在算法本身，而在它把\"配额\"从静态配置变成可更新的后验。凡是样本价值随训练漂移、且单 prompt 统计足以支撑后验的场景，这笔后验更新的开销值得付；凡是漂移慢或统计稀疏的场景，规则与课程调度的确定性反而更省。选型的终点不是选出最强算法，而是让滞后预算与漂移时间尺度对齐——对齐了，简单算法也够用；对不齐，再精细的后验也只是在追一个已经跑掉的分布。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 长尾样本与rollout吞吐</td></tr><tr><td>解决什么</td><td>RL rollout的样本价值随训练进程漂移，固定按prompt长度或前缀局部性调度会把算力分配给已无信息量的简单题，…</td></tr><tr><td>一句话机制</td><td>把每个prompt的采样预算视为上下文bandit问题，用历史reward方差与通过率估计其信息增益，按UCB式规则动…</td></tr><tr><td>代价与失效</td><td>bandit统计依赖历史reward，训练早期统计稀疏时优先级估计噪声大，可能错配算力；非均匀采样使GRPO组内样本数不一致，advant…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-rollout-bandit-scheduling · 共 8 个片段</p>\n";break;}}})();
